#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Kyrgyz Rating (Кыргыз Рейтинг), модуль АПК — движок предварительной индикативной оценки
кредитоспособности компаний агропромышленного комплекса Кыргызстана.

Все показатели измеримы: аналитик вводит только данные из документов (числа, отметки «да/нет»,
таблицы по годам), программа сама переводит их в баллы, применяет ограничения и корректировки,
строит базовый прогноз, стресс-сценарии и отчёт для рейтингового комитета.

Python-движок — единственный источник правил: подсекторы, веса, пороги, поля ввода и обучающие
примеры выгружаются в config.json для интерфейса. Логика расчёта повторена в web/src/engine.js
строка в строку; совпадение проверяется кодом расчёта (хэшем результата).

Команды:
  python kg_agro_rating.py selftest                 # самопроверка (примеры методики, повторяемость, архив, настройки)
  python kg_agro_rating.py demo [ключ]              # отчёт по обучающему примеру
  python kg_agro_rating.py rate case.json [--md отчёт.md] [--json результат.json]
  python kg_agro_rating.py export-config [файл]     # конфиг для интерфейса (единый источник правил)
  python kg_agro_rating.py serve [--port 8765] [--archive файл.json]
  python kg_agro_rating.py archive | archive-csv файл.csv | archive-import файл.json | archive-verify
  python kg_agro_rating.py monitoring [--today ДД.ММ.ГГГГ]  # сроки пересмотра и рейтинговые действия
  python kg_agro_rating.py next-year данные.json [новые.json] [--today ДД.ММ.ГГГГ]  # перенос на следующий отчётный год
  python kg_agro_rating.py nbkr бюллетень.xls [--settings настройки.json] [--out настройки.json]  # ставки НБКР по отраслям
"""

