# 1. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ (детерминированные, совпадают с JS 1:1)
# ════════════════════════════════════════════════════════════════════════════

def is_num(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x)

def nz(x):
    return x if is_num(x) else 0

def q(x, digits):
    """Округление «половина вверх» — одинаково в Python и JS."""
    if not is_num(x):
        return None
    m = 10 ** digits
    r = math.floor(x * m + 0.5 + 1e-9) / m
    if r == 0:
        r = 0.0
    return r

def fmt_fixed(x, digits):
    if not is_num(x):
        return None
    r = q(x, digits)
    return "%.*f" % (digits, r)

def fmt_num(x, d=2):
    if not is_num(x):
        return "—"
    s = fmt_fixed(x, d)
    neg = s.startswith("-")
    if neg:
        s = s[1:]
    if "." in s:
        ip, fp = s.split(".")
    else:
        ip, fp = s, ""
    grp = ""
    while len(ip) > 3:
        grp = " " + ip[-3:] + grp
        ip = ip[:-3]
    out = ip + grp + ("," + fp if fp else "")
    return ("−" if neg else "") + out

def canon_num(x):
    """Каноническая запись числа (6 знаков после запятой, целочисленная арифметика — одинаково в Python и JS)."""
    if float(x).is_integer() and abs(x) < 1e15:
        return str(int(x))
    m = math.floor(x * 1e6 + 0.5)
    if m == 0:
        return "0"
    neg = m < 0
    s = str(abs(int(m))).rjust(7, "0")
    ip = s[:-6]
    fp = s[-6:].rstrip("0")
    return ("-" if neg else "") + ip + ("." + fp if fp else "")

def canonical(obj):
    if obj is None:
        return "null"
    if isinstance(obj, bool):
        return "true" if obj else "false"
    if isinstance(obj, (int, float)):
        if not math.isfinite(obj):
            return "null"
        return canon_num(obj)
    if isinstance(obj, str):
        return json.dumps(obj, ensure_ascii=False)
    if isinstance(obj, (list, tuple)):
        return "[" + ",".join(canonical(v) for v in obj) + "]"
    if isinstance(obj, dict):
        return "{" + ",".join(json.dumps(str(k), ensure_ascii=False) + ":" + canonical(obj[k]) for k in sorted(obj.keys())) + "}"
    return json.dumps(str(obj), ensure_ascii=False)

def sha256_hex(s):
    return hashlib.sha256(s.encode("utf-8")).hexdigest()

_NUM_RE = re.compile(r"^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$")

def parse_num(v):
    """Число из ввода: допускает пробелы, неразрывные пробелы и запятую."""
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return v if math.isfinite(v) else None
    s = str(v).strip().replace(" ", "").replace(" ", "").replace(" ", "").replace(",", ".")
    s = s.replace("−", "-")
    if s == "" or s in ("-", "."):
        return None
    if not _NUM_RE.match(s):
        return None
    try:
        x = float(s)
    except ValueError:
        return None
    return x if math.isfinite(x) else None

_DATE_RE = re.compile(r"^\s*(\d{1,2})\.(\d{1,2})\.(\d{4})\s*$")

def parse_date(s):
    """ДД.ММ.ГГГГ → (год, месяц, день) или None."""
    if not isinstance(s, str):
        return None
    m = _DATE_RE.match(s)
    if not m:
        return None
    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if mo < 1 or mo > 12 or d < 1 or d > 31:
        return None
    return (y, mo, d)

def months_between(a, b):
    """Полных месяцев от даты a до даты b (обе — кортежи год, месяц, день)."""
    m = (b[0] - a[0]) * 12 + (b[1] - a[1])
    if b[2] < a[2]:
        m = m - 1
    return m

def text_ok(s):
    return isinstance(s, str) and s.strip() != ""

