# ── Метрические индикаторы (раздел В.2): правило «a–b» — лучшая граница входит в лучшую категорию
def _H(*v):
    return [[CATEGORIES[i], ">=", v[i]] for i in range(7)]

def _L(*v):
    return [[CATEGORIES[i], "<=", v[i]] for i in range(7)]

def I(code, sf, name, w, unit, rules, other="Ca", labels=None, hint="", dec=1, na=None):
    return {"code": code, "sf": sf, "name": name, "w": w, "unit": unit, "rules": rules, "else": other,
            "labels": labels, "hint": hint, "dec": dec, "na": na}

