# when — условия показа поля (все должны выполняться):
#   "sub:XXX[,YYY]"  — среди действующих подсекторов (основной или сегмент холдинга от 10%) есть XXX или YYY
#   "main:XXX[,YYY]" — основной подсектор XXX или YYY;  "notmain:…" — основной подсектор не из списка
#   "fx" — отчётность не в сомах; "interim" — только промежуточная отчётность; "seasonal" — правило сезонного долга;
#   "int" — интегрированный агрохолдинг; "garden" — есть многолетние насаждения; "annual" — есть однолетние культуры;
#   "reval" — основные средства переоценивались; "nоreval" — не переоценивались; "group" — компания входит в группу;
#   "bp" — есть бизнес-план; "poultry" — птицефабрика (MEA); "nopoultry"

def F(key, card, label, ftype, hint="", doc="", unit="", when=None, options=None, placeholder="",
      group="", money=None, ind=None, src=None, aff=(), ann=False):
    return {"key": key, "card": card, "label": label, "type": ftype, "hint": hint, "doc": doc, "unit": unit,
            "when": list(when) if when else [], "options": options, "placeholder": placeholder, "group": group,
            "money": money, "ind": ind, "src": src, "aff": list(aff), "ann": ann}

def SRC(key, card, label, ind, when=None, group=""):
    return F(key, card, label, "source", "Документ, из которого взято значение: название, номер, дата. Без источника значение не учитывается и индикатор получает 12 баллов (как «нет данных»).",
             when=when, group=group, ind=ind)

