# ════════════════════════════════════════════════════════════════════════════
# 6. НАСТРОЙКИ (веса и пороги количественных показателей)
# ════════════════════════════════════════════════════════════════════════════

BOUND_KEYS = ["rev", "mpm", "de", "ic", "rcf", "liq", "overdue", "payables"]

def default_settings():
    """Настройки: изменения весов и порогов по подсекторам (только отличия от методологии) и общие параметры."""
    return {"subsectors": {}, "market_rate": 16, "low_rate_share": 50, "nbkr": None}

def sub_default_params(c):
    """Веса и пороги подсектора c по методологии."""
    p = {"weights": {}, "bounds": {}}
    for sf in SUBFACTORS:
        p["weights"][sf["code"]] = sf["weight"]
    for k in BOUND_KEYS:
        p["bounds"][k] = list(METRICS[k]["bounds"])
    if c in SEGMENT_SUBS:
        p["margin"] = list(MARGIN_GROUPS[SUBSECTORS[c]["group"]]["bounds"])
        if SUBSECTORS[c]["nat"]["bounds"]:
            p["nat"] = list(SUBSECTORS[c]["nat"]["bounds"])
    return p

def _valid_bounds(b, direction):
    if not isinstance(b, list) or len(b) != 9:
        return False
    for x in b:
        if not is_num(x):
            return False
    for i in range(8):
        if direction == "higher" and not (b[i] > b[i + 1]):
            return False
        if direction == "lower" and not (b[i] < b[i + 1]):
            return False
    return True

def _norm_bounds(v, direction):
    if not isinstance(v, list):
        return None
    cand = [parse_num(x) for x in v]
    return cand if _valid_bounds(cand, direction) else None

def _same(a, b):
    if len(a) != len(b):
        return False
    for i in range(len(a)):
        if a[i] != b[i]:
            return False
    return True

def _norm_override(c, ov, notes, glob=None):
    """Проверяет изменения одного подсектора; оставляет только то, что отличается от методологии
    (рыночная ставка — то, что отличается от общей ставки glob)."""
    out = {}
    if not isinstance(ov, dict):
        return out
    d = sub_default_params(c)
    name = SUBSECTORS[c]["name"]
    w = ov.get("weights")
    if isinstance(w, dict):
        ok = True
        tot = 0
        vals = {}
        for code in SF_CODES:
            x = parse_num(w.get(code))
            if x is None or x < 0:
                ok = False
                break
            vals[code] = x
            tot += x
        if ok and tot > 0:
            diff = False
            for code in SF_CODES:
                if vals[code] != d["weights"][code]:
                    diff = True
            if diff:
                out["weights"] = vals
        else:
            notes.append("%s: веса подфакторов заданы неверно — используются веса методологии." % name)
    b = ov.get("bounds")
    if isinstance(b, dict):
        ob = {}
        for k in BOUND_KEYS:
            if k in b:
                cand = _norm_bounds(b[k], METRICS[k]["dir"])
                if cand is None:
                    notes.append("%s: пороги «%s» заданы неверно — используются пороги методологии." % (name, METRICS[k]["name"]))
                elif not _same(cand, d["bounds"][k]):
                    ob[k] = cand
        if len(ob) > 0:
            out["bounds"] = ob
    for key, label in (("margin", "маржи EBITDA (3.1)"), ("nat", "натурального объёма (1.6)")):
        if key in ov and key in d:
            cand = _norm_bounds(ov.get(key), "higher")
            if cand is None:
                notes.append("%s: пороги %s заданы неверно — используются пороги методологии." % (name, label))
            elif not _same(cand, d[key]):
                out[key] = cand
    if "market_rate" in ov and ov.get("market_rate") is not None and ov.get("market_rate") != "":
        x = parse_num(ov.get("market_rate"))
        if x is None or not (0.1 <= x <= 100):
            notes.append("%s: рыночная ставка задана неверно (нужно 0,1–100%%) — используется общая ставка." % name)
        elif x != (glob if glob is not None else default_settings()["market_rate"]):
            out["market_rate"] = x
    ns = ov.get("nbkr_sector")
    if ns not in (None, ""):
        if ns not in dict(NBKR_SECTORS):
            notes.append("%s: неизвестная отрасль бюллетеня НБКР «%s» — используется отрасль по умолчанию." % (name, ns))
        elif ns != NBKR_DEFAULT_MAP.get(c):
            out["nbkr_sector"] = ns
    return out

def normalize_settings(raw):
    """Проверяет настройки; всё некорректное заменяется значениями методологии.
    Поддерживает прежний формат (общие веса и пороги для всех подсекторов)."""
    out = default_settings()
    notes = []
    if not isinstance(raw, dict):
        return out, notes
    for k, lo, hi in (("market_rate", 0.1, 100), ("low_rate_share", 1, 100)):
        x = parse_num(raw.get(k))
        if x is not None:
            if lo <= x <= hi:
                out[k] = x
            else:
                notes.append("Параметр «%s» вне допустимого диапазона — используется стандартный." % k)
    if raw.get("nbkr") is not None:
        out["nbkr"] = norm_nbkr(raw.get("nbkr"), notes)
    subs = raw.get("subsectors")
    if isinstance(subs, dict):
        for c in SUBSECTOR_ORDER:
            if c in subs:
                ov = _norm_override(c, subs[c], notes, out["market_rate"])
                if len(ov) > 0:
                    out["subsectors"][c] = ov
    elif any(k in raw for k in ("weights", "bounds", "margin", "nat")):
        # прежний формат: общие настройки переносятся в каждый подсектор
        for c in SUBSECTOR_ORDER:
            ov = {}
            if "weights" in raw:
                ov["weights"] = raw.get("weights")
            if "bounds" in raw:
                ov["bounds"] = raw.get("bounds")
            if c in SEGMENT_SUBS:
                m = raw.get("margin")
                g = SUBSECTORS[c]["group"]
                if isinstance(m, dict) and g in m:
                    ov["margin"] = m[g]
                n = raw.get("nat")
                if isinstance(n, dict) and c in n:
                    ov["nat"] = n[c]
            ov = _norm_override(c, ov, notes, out["market_rate"])
            if len(ov) > 0:
                out["subsectors"][c] = ov
    uniq = []
    for n_ in notes:
        if n_ not in uniq:
            uniq.append(n_)
    return out, uniq

def settings_changed(s):
    d = default_settings()
    return canonical(s) != canonical(d)

def effective_settings(st, ctx):
    """Веса и пороги, которые действуют для компании: по выбранному подсектору (для агрохолдинга — по сегментам)."""
    main = ctx["main"]
    subs = st["subsectors"]
    ov = subs.get(main, {}) if main is not None else {}
    base = sub_default_params(main if main is not None else "INT")
    w = {}
    src_w = ov.get("weights") or base["weights"]
    for code in SF_CODES:
        w[code] = src_w[code]
    b = {}
    ob = ov.get("bounds") or {}
    for k in BOUND_KEYS:
        b[k] = list(ob[k]) if k in ob else list(base["bounds"][k])
    nat = {}
    msub = {}
    for c in SEGMENT_SUBS:
        o = subs.get(c, {})
        nb = SUBSECTORS[c]["nat"]["bounds"]
        nat[c] = list(o["nat"]) if "nat" in o else (list(nb) if nb else None)
        msub[c] = list(o["margin"]) if "margin" in o else None
    margin = {}
    for g in ["I", "II", "III"]:
        margin[g] = list(MARGIN_GROUPS[g]["bounds"])
    d0 = default_settings()
    changed = st["market_rate"] != d0["market_rate"] or st["low_rate_share"] != d0["low_rate_share"]
    rel = [main] + list(ctx["segs"]) if main is not None else []
    for c in rel:
        if c in subs:
            changed = True
    # рыночная ставка: своя у подсектора → бюллетень НБКР за отчётный период → общая;
    # агрохолдинг без своей ставки и без своей отрасли бюллетеня — по долям сегментов
    mr, msrc, mnote = st["market_rate"], "all", None
    if main is not None:
        if ctx["group"] == "MIX" and "market_rate" not in ov and not ov.get("nbkr_sector"):
            parts = [(c, ctx["shares"][c] / 100.0) for c in SEGMENT_SUBS if ctx["shares"][c] > 0]
            got = [(c, sh) + _sub_market(st, ctx, c) for c, sh in parts]
            if any(g[3] != "all" for g in got):
                mr = q(sum(sh * r for c, sh, r, _s, _n in got), 4)
                msrc = "segments"
                mnote = "; ".join("%s %s%% × %s%%" % (SUBSECTORS[c]["name"], fmt_num(sh * 100, 0), fmt_pct(r)) for c, sh, r, _s, _n in got)
        else:
            mr, msrc, mnote = _sub_market(st, ctx, main)
    return {"weights": w, "bounds": b, "margin": margin, "margin_sub": msub, "nat": nat,
            "market_rate": mr, "market_src": msrc, "market_note": mnote, "low_rate_share": st["low_rate_share"], "changed": changed}

def _sub_market(st, ctx, c):
    """Рыночная ставка подсектора c: своя из настроек → бюллетень НБКР за отчётный период → общая."""
    ov = st["subsectors"].get(c, {})
    if "market_rate" in ov:
        return ov["market_rate"], "sub", None
    nb = st.get("nbkr")
    sec = nbkr_sector_of(st, c)
    if nb is not None and sec is not None:
        r, lab = nbkr_rate(nb, sec, period_info(ctx["raw"]))
        if r is not None:
            return q(r, 2), "nbkr", "%s, табл. IV.2.19: %s, %s — новые кредиты в сомах" % (nb["title"], NBKR_SECTOR_NAMES[sec], lab)
        msg = "Бюллетень НБКР (%s), отрасль «%s»: %s — используется общая ставка из «Настроек» (%s%%)." % (nb["title"], NBKR_SECTOR_NAMES[sec], lab, fmt_pct(st["market_rate"]))
        if msg not in ctx["warnings"]:
            ctx["warnings"].append(msg)
    return st["market_rate"], "all", None

# ════════════════════════════════════════════════════════════════════════════
# 7. БАЛЛЫ: интерполяция, категории, шкала оценки
# ════════════════════════════════════════════════════════════════════════════

def score_value(value, bounds, direction):
    s = BOUNDARY_SCORES
    if direction == "higher":
        if value >= bounds[0]:
            return s[0]
        if value <= bounds[8]:
            return s[8]
        for i in range(8):
            b0 = bounds[i]
            b1 = bounds[i + 1]
            if value <= b0 and value > b1:
                return s[i] + (b0 - value) / (b0 - b1) * (s[i + 1] - s[i])
    else:
        if value <= bounds[0]:
            return s[0]
        if value >= bounds[8]:
            return s[8]
        for i in range(8):
            b0 = bounds[i]
            b1 = bounds[i + 1]
            if value >= b0 and value < b1:
                return s[i] + (value - b0) / (b1 - b0) * (s[i + 1] - s[i])
    return s[8]

def category_for_value(value, bounds, direction, strict=False):
    idx = 0
    for i in range(1, 8):
        b = bounds[i]
        if direction == "higher":
            if value < b:
                idx += 1
        elif strict:
            if value >= b:
                idx += 1
        else:
            if value > b:
                idx += 1
    return CATEGORIES[idx]

def category_for_score(score):
    cuts = [1.5, 4.5, 7.5, 10.5, 13.5, 16.5, 19.5]
    idx = 0
    for c in cuts:
        if score > c:
            idx += 1
    return CATEGORIES[idx]

def rating_index(total):
    t = q(total, 6)
    idx = len(RATING_SCALE) - 1
    for i in range(len(RATING_SCALE)):
        up = RATING_SCALE[i]["upper"]
        if up is not None and t <= up:
            idx = i
            break
    return idx

def rating_info(idx, total=None):
    row = RATING_SCALE[idx]
    lower = RATING_SCALE[idx - 1]["upper"] if idx > 0 else 0.5
    info = {"index": idx, "internal": row["internal"], "national": row["national"], "lower": lower, "upper": row["upper"],
            "headroom": None, "to_better": None}
    if total is not None and row["upper"] is not None:
        info["headroom"] = q(row["upper"] - total, 2)
        info["to_better"] = q(total - lower, 2)
    return info

def rating_group_key(national):
    s = national[2:].replace("+", "").replace("−", "")
    return s

def rule_category(value, rules, other):
    for r in rules:
        cat, op, th = r[0], r[1], r[2]
        if op == ">=" and value >= th:
            return cat
        if op == "<=" and value <= th:
            return cat
        if op == ">" and value > th:
            return cat
    return other

def blend_rules(rules_a, rules_b, wa):
    """Смешанная шкала: каждая граница = wa × граница A + (1 − wa) × граница B."""
    out = []
    for i in range(len(rules_a)):
        out.append([rules_a[i][0], rules_a[i][1], rules_a[i][2] * wa + rules_b[i][2] * (1 - wa)])
    return out

# ════════════════════════════════════════════════════════════════════════════
# 8. ВВОД: разбор, валюта, подсектор, условия показа полей
# ════════════════════════════════════════════════════════════════════════════

HAIRCUT_KEYS = ["rev_0", "op_0", "da_0", "bio_0", "once_0", "gain_0", "young_0"]

def raw_bool(v):
    if v is True:
        return True
    if isinstance(v, str) and v.strip().lower() in ("1", "true", "да", "yes"):
        return True
    if is_num(v) and v == 1:
        return True
    return False

def raw_str(v):
    if isinstance(v, str):
        return v.strip()
    if is_num(v):
        return canon_num(v)
    return ""

def _dmy(t):
    return "%02d.%02d.%04d" % (t[2], t[1], t[0])

def period_checks(ctx):
    """Согласованность отчётного периода. На расчёт не влияет — только предупреждения."""
    w = ctx["warnings"]
    ry, bd, ev = ctx["report_year"], ctx["bal_date"], ctx["eval_date"]
    if ry is None:
        if raw_str(ctx["raw"].get("report_year")) == "":
            w.append("Не указан последний полный финансовый год: годы в таблице «по годам», возраст оборудования и насаждений не определены.")
        else:
            w.append("Последний полный финансовый год указан неверно — нужен год от 1990 до 2100.")
    if ry is not None and bd is not None:
        if ctx["fy_type"] == "year":
            if bd != (ry, 12, 31):
                w.append("Дата баланса %s не совпадает с концом последнего полного финансового года (31.12.%d) — проверьте год и дату баланса." % (_dmy(bd), ry))
        elif bd[0] == ry + 1 and bd[1] == 12 and bd[2] == 31:
            w.append("Дата баланса %s — конец года: выберите годовую отчётность и последний полный финансовый год %d." % (_dmy(bd), ry + 1))
        elif bd[0] != ry + 1:
            w.append("Дата баланса %s: промежуточная отчётность и LTM относятся к %d году — году после последнего полного финансового года %d." % (_dmy(bd), ry + 1, ry))
    if ry is not None and ev is not None and ry >= ev[0]:
        w.append("Последний полный финансовый год %d ещё не закончился на дату оценки %s." % (ry, _dmy(ev)))
    if bd is not None and ev is not None and bd > ev:
        w.append("Дата баланса %s позже даты оценки %s." % (_dmy(bd), _dmy(ev)))

def build_ctx(raw, settings, haircut=None):
    ctx = {"raw": raw if isinstance(raw, dict) else {}, "settings": settings, "errors": [], "warnings": [], "haircut": haircut}
    r = ctx["raw"]
    cur = raw_str(r.get("currency")) or "KGS"
    ctx["currency"] = cur
    ctx["fx"] = cur != "KGS"
    ctx["rate_avg"] = 1
    ctx["rate_end"] = 1
    if ctx["fx"]:
        ra = parse_num(r.get("rate_avg"))
        re_ = parse_num(r.get("rate_end"))
        if ra is None or ra <= 0 or re_ is None or re_ <= 0:
            ctx["errors"].append("Отчётность не в сомах: укажите средний курс НБКР за период и курс на дату баланса.")
        else:
            ctx["rate_avg"] = ra
            ctx["rate_end"] = re_
    fy = raw_str(r.get("fy_type")) or "year"
    ctx["fy_type"] = fy
    ctx["ann"] = 1
    ctx["annualized"] = False
    if fy == "interim":
        mo = parse_num(r.get("interim_months"))
        if mo not in (3, 6, 9):
            mo = 6
        ctx["interim_months"] = mo
        ctx["ann"] = 12.0 / mo
        ctx["annualized"] = True
    ry = parse_num(r.get("report_year"))
    ctx["report_year"] = int(ry) if ry is not None and ry >= 1990 and ry <= 2100 else None
    hy = parse_num(r.get("harvest_year"))
    ctx["harvest_year"] = int(hy) if hy is not None and hy >= 1990 and hy <= 2100 else ctx["report_year"]
    ctx["eval_date"] = parse_date(r.get("eval_date"))
    ctx["bal_date"] = parse_date(r.get("bal_date"))
    period_checks(ctx)
    classify(ctx)
    ctx["st_all"] = settings
    ctx["settings"] = effective_settings(settings, ctx)
    return ctx

def gnum(ctx, key):
    v = parse_num(ctx["raw"].get(key))
    if v is None:
        return None
    f = FIELD.get(key)
    if f is not None:
        if f["money"] == "flow":
            v = v * ctx["rate_avg"]
        elif f["money"] == "stock":
            v = v * ctx["rate_end"]
        if f["ann"]:
            v = v * ctx["ann"]
    if ctx["haircut"] is not None and key in HAIRCUT_KEYS:
        v = v * ctx["haircut"]
    return v

def gbool(ctx, key):
    return raw_bool(ctx["raw"].get(key))

def gstr(ctx, key):
    return raw_str(ctx["raw"].get(key))

def gtable(ctx, name):
    rows = ctx["raw"].get(name)
    if not isinstance(rows, list):
        return []
    cols = TABLES[name]["cols"]
    out = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        d = {}
        empty = True
        for c in cols:
            v = row.get(c["key"])
            if c["type"] == "num":
                x = parse_num(v)
                if x is not None:
                    empty = False
                    if c.get("money") == "flow":
                        x = x * ctx["rate_avg"]
                    elif c.get("money") == "stock":
                        x = x * ctx["rate_end"]
                d[c["key"]] = x
            elif c["type"] == "bool":
                d[c["key"]] = raw_bool(v)
            else:
                s = raw_str(v)
                if s != "" and c["type"] != "select":
                    empty = False
                d[c["key"]] = s
        if not empty:
            out.append(d)
    return out

def _shares(r):
    shares = {}
    tot = 0
    for c in SEGMENT_SUBS:
        v = parse_num(r.get("sh_" + c))
        if v is None or v < 0:
            v = 0
        shares[c] = v
        tot += v
    norm = {}
    for c in SEGMENT_SUBS:
        norm[c] = shares[c] * 100.0 / tot if tot > 0 else 0
    return norm, tot

def _set_segments(ctx, main, norm):
    ctx["main"] = main
    ctx["is_int"] = main == "INT"
    segs = []
    if ctx["is_int"]:
        for c in SEGMENT_SUBS:
            if norm[c] >= 10:
                segs.append(c)
    else:
        segs = [main]
    ctx["segs"] = segs
    sw = 0
    for c in segs:
        sw += norm[c]
    ctx["seg_w"] = {}
    for c in segs:
        ctx["seg_w"][c] = norm[c] / sw if sw > 0 else 0

def rule_a2(norm):
    """Подсектор по долям выручки (раздел А.2): 60% и более — основной; иначе два вида по 15% — агрохолдинг; иначе наибольший."""
    best = None
    n15 = 0
    for c in SEGMENT_SUBS:
        if best is None or norm[c] > norm[best]:
            best = c
        if norm[c] >= 15:
            n15 += 1
    if norm[best] >= 60:
        return best, best, n15
    if n15 >= 2:
        return "INT", best, n15
    return best, best, n15

def sub_label(c):
    return SUBSECTORS[c]["name"] if c in SUBSECTORS else str(c)

def classify(ctx):
    r = ctx["raw"]
    sel = raw_str(r.get("subsector"))
    ctx["sub_selected"] = sel
    ctx["sub_source"] = None
    ctx["main"] = None
    ctx["segs"] = []
    ctx["seg_w"] = {}
    ctx["is_int"] = False
    norm = {}
    for c in SEGMENT_SUBS:
        norm[c] = 0
    tot = 0
    if sel != "" and sel not in SUBSECTORS:
        ctx["errors"].append("Неизвестный подсектор «%s» — выберите подсектор из списка." % sel)
    elif sel != "" and sel != "INT":
        # подсектор выбран: доли выручки не нужны, весь бизнес — один подсектор
        norm[sel] = 100.0
        tot = 100.0
        ctx["sub_source"] = "selected"
        _set_segments(ctx, sel, norm)
    elif sel == "INT":
        norm, tot = _shares(r)
        ctx["sub_source"] = "selected"
        if tot <= 0:
            ctx["errors"].append("Для интегрированного агрохолдинга укажите доли выручки по видам деятельности.")
        else:
            if abs(tot - 100) > 1:
                ctx["warnings"].append("Сумма долей выручки по видам деятельности %s%% — программа пересчитала доли до 100%%." % fmt_num(tot, 1))
            a2, best, n15 = rule_a2(norm)
            if a2 != "INT":
                if norm[best] >= 60:
                    ctx["warnings"].append("По правилу А.2 компания не является агрохолдингом: «%s» даёт %s%% выручки (60%% и более) — проверьте выбор подсектора." % (sub_label(best), fmt_num(norm[best], 1)))
                else:
                    ctx["warnings"].append("По правилу А.2 агрохолдинг — не менее двух видов деятельности с долей 15%% выручки и более; сейчас таких %d — проверьте выбор подсектора." % n15)
            _set_segments(ctx, "INT", norm)
            if len(ctx["segs"]) == 0:
                ctx["errors"].append("Ни один вид деятельности агрохолдинга не даёт 10% выручки — сегменты для расчёта не определены.")
                ctx["main"] = None
                ctx["is_int"] = False
    else:
        # подсектор не выбран (записи прежней версии): определяется по долям выручки
        norm, tot = _shares(r)
        if tot <= 0:
            ctx["errors"].append("Выберите подсектор в профиле компании.")
        else:
            if abs(tot - 100) > 1:
                ctx["warnings"].append("Сумма долей выручки по видам деятельности %s%% — программа пересчитала доли до 100%%." % fmt_num(tot, 1))
            a2, _best, _n15 = rule_a2(norm)
            ctx["sub_source"] = "shares"
            _set_segments(ctx, a2, norm)
            ctx["warnings"].append("Подсектор не выбран — программа определила его по долям выручки (правило А.2): «%s». Выберите подсектор в профиле компании." % sub_label(a2))
    ctx["shares"] = norm
    ctx["shares_total"] = tot
    # группы маржи
    gsh = {"I": 0, "II": 0, "III": 0}
    for c in SEGMENT_SUBS:
        gsh[sub_group(ctx, c)] += norm[c] / 100.0
    ctx["gshare"] = gsh
    if ctx["main"] is None:
        ctx["group"] = None
        ctx["g3"] = 0
    elif ctx["is_int"]:
        ctx["group"] = "MIX"
        ctx["g3"] = gsh["III"]
    else:
        ctx["group"] = sub_group(ctx, ctx["main"])
        ctx["g3"] = 1 if ctx["group"] == "III" else 0
    sea = 0
    for c in SEASONAL_SUBS:
        sea += norm[c]
    ctx["seasonal"] = ctx["main"] in SEASONAL_SUBS or (ctx["is_int"] and sea >= 30)
    p = parse_num(r.get("crp_perennial_share"))
    if p is None:
        p = 0
    p = max(0, min(100, p))
    ctx["crp_p"] = p
    crp = "CRP" in ctx["segs"]
    ctx["crp"] = crp
    ctx["garden"] = crp and p > 0
    ctx["annual"] = crp and p < 100
    base = ctx["main"]
    if ctx["is_int"]:
        base = None
        for c in ctx["segs"]:
            if base is None or norm[c] > norm[base]:
                base = c
    ctx["prot_sub"] = base
    ctx["prot"] = SUBSECTORS[base]["protect5"] if base is not None else "vet"

def sub_group(ctx, c):
    if c == "FSH":
        v = parse_num(ctx["raw"].get("fsh_proc_share"))
        return "II" if (v is not None and v >= 50) else "III"
    return SUBSECTORS[c]["group"]

def cond_ok(ctx, token):
    if ":" in token:
        kind, arg = token.split(":", 1)
        lst = arg.split(",")
        if kind == "sub":
            for c in lst:
                if c in ctx["segs"]:
                    return True
            return False
        if kind == "seg":
            return ctx["is_int"] and arg in ctx["segs"]
        if kind == "main":
            return ctx["main"] in lst
        if kind == "notmain":
            return ctx["main"] is not None and ctx["main"] not in lst
        if kind == "prot":
            return ctx["prot"] == arg
        return True
    if token == "fx":
        return ctx["fx"]
    if token == "interim":
        return ctx["fy_type"] == "interim"
    if token == "seasonal":
        return ctx["seasonal"]
    if token == "int":
        return ctx["is_int"]
    if token == "shares":
        return ctx["sub_selected"] == "INT" or (ctx["sub_selected"] == "" and ctx["shares_total"] > 0)
    if token == "notint":
        return not ctx["is_int"]
    if token == "garden":
        return ctx["garden"]
    if token == "annual":
        return ctx["annual"]
    if token == "reval":
        return gbool(ctx, "f23_reval")
    if token == "noreval":
        return not gbool(ctx, "f23_reval")
    if token == "group":
        return gbool(ctx, "in_group")
    if token == "bp":
        return not gbool(ctx, "bp_none")
    if token == "main3":
        return ctx["g3"] > 0
    return True

def field_visible(ctx, f):
    for t in f["when"]:
        if not cond_ok(ctx, t):
            return False
    return True

# ════════════════════════════════════════════════════════════════════════════
# 9. ИНДИКАТОРЫ И ПОДФАКТОРЫ
# ════════════════════════════════════════════════════════════════════════════

def ind_eval(code, value, src_ok, na=False, rules=None, note=None, force_cat=None, unit=None):
    d = IND[code]
    res = {"code": code, "name": d["name"], "w": d["w"], "unit": d["unit"] if unit is None else unit, "dec": d["dec"],
           "value": value, "src": bool(src_ok), "na": bool(na), "missing": False, "cat": None, "score": None, "note": note}
    if na:
        return res
    if force_cat is not None and src_ok:
        res["cat"] = force_cat
        res["score"] = CATEGORY_SCORES[force_cat]
        return res
    if value is None or not src_ok:
        res["missing"] = True
        res["score"] = DEFAULT_SCORE
        if value is not None and not src_ok:
            res["note"] = "Значение без источника не учитывается"
        return res
    rl = rules if rules is not None else d["rules"]
    res["cat"] = rule_category(value, rl, d["else"])
    res["score"] = CATEGORY_SCORES[res["cat"]]
    return res

def metric_score(inds):
    """Взвешенное среднее индикаторов (В.2); правило более 50% веса без данных (В.3)."""
    sw = 0
    s = 0
    miss_w = 0
    napp = 0
    nmiss = 0
    for x in inds:
        if x["na"]:
            continue
        napp += 1
        sw += x["w"]
        s += x["w"] * x["score"]
        if x["missing"]:
            miss_w += x["w"]
            nmiss += 1
    if sw <= 0:
        return {"score": DEFAULT_SCORE, "raw": DEFAULT_SCORE, "all_default": True, "miss_share": 1, "caps": []}
    raw = q(s / sw, 2)
    out = {"score": raw, "raw": raw, "all_default": nmiss == napp, "miss_share": miss_w / sw, "caps": []}
    if miss_w / sw > 0.5 and raw < 15:
        out["score"] = 15
        out["caps"].append({"name": "Недостаточно данных", "text": "Индикаторы без данных составляют более 50% веса подфактора — не лучше B (15)", "level": 15})
    return out

def apply_cap(res, level, name, text, exact=False):
    if exact:
        if res["score"] != level:
            res["score"] = level
        res["caps"].append({"name": name, "text": text, "level": level, "exact": True})
        return
    if res["score"] < level:
        res["score"] = level
        res["caps"].append({"name": name, "text": text, "level": level})
    else:
        res["caps"].append({"name": name, "text": text, "level": level, "inactive": True})

def src_ok(ctx, key):
    return text_ok(gstr(ctx, key))

def quant_result(code, metric, value, bounds, direction, strict=False, special=None, unit=None, note=None):
    res = {"code": code, "metric": metric, "value": value, "unit": unit if unit is not None else METRICS[metric]["unit"],
           "caps": [], "all_default": False, "note": note, "bounds": bounds, "dir": direction}
    if special is not None:
        res["raw"] = special
        res["score"] = special
        res["cat"] = category_for_score(special)
        return res
    if value is None:
        res["raw"] = DEFAULT_SCORE
        res["score"] = DEFAULT_SCORE
        res["cat"] = None
        res["all_default"] = True
        return res
    sc = q(score_value(value, bounds, direction), 2)
    res["raw"] = sc
    res["score"] = sc
    res["cat"] = category_for_value(value, bounds, direction, strict)
    return res

# ── Ряды по годам: EBITDA и маржа ───────────────────────────────────────

def year_ebitda(ctx, y):
    rev = gnum(ctx, "rev_%d" % y)
    op = gnum(ctx, "op_%d" % y)
    if rev is None or op is None:
        return None
    da = nz(gnum(ctx, "da_%d" % y))
    e = op + da - nz(gnum(ctx, "bio_%d" % y)) - nz(gnum(ctx, "once_%d" % y)) - nz(gnum(ctx, "gain_%d" % y))
    if ctx["garden"]:
        e = e + nz(gnum(ctx, "young_%d" % y))
    return {"year": y, "rev": rev, "ebitda": e, "margin": (e / rev * 100.0) if rev > 0 else None}

def margin_series(ctx):
    """Последовательные годы от последнего назад, пока есть выручка и операционная прибыль."""
    out = []
    for y in range(5):
        r = year_ebitda(ctx, y)
        if r is None or r["margin"] is None:
            break
        out.append(r)
    return out

# ── Блок 1 ───────────────────────────────────────────────────────────────

def sf_11(ctx):
    rev = gnum(ctx, "rev_0")
    v = rev / 1e6 if rev is not None else None
    res = quant_result("1.1", "rev", v, ctx["settings"]["bounds"]["rev"], "higher")
    return res

def sf_12(ctx):
    share = parse_num(ctx["raw"].get("m12_share"))
    other = parse_num(ctx["raw"].get("m12_other"))
    st = gstr(ctx, "s12_type")
    indep = st in INDEPENDENT_SOURCES and src_ok(ctx, "s12")
    note = None
    if not indep and (share is not None or other is not None):
        note = "Доля не подтверждена независимым источником — индикаторы 1.2.А и 1.2.Б считаются без данных"
    ratio = None
    if share is not None and other is not None and other > 0:
        ratio = share / other
    a = ind_eval("1.2.А", share, indep)
    b = ind_eval("1.2.Б", ratio, indep and other is not None)
    if not indep and src_ok(ctx, "s12"):
        for x in (a, b):
            if x["value"] is not None:
                x["note"] = "Источник не независимый — значение не учитывается"
    inds = [a, b]
    res = metric_score(inds)
    res["indicators"] = inds
    res["note"] = note
    return res

def sf_13(ctx):
    inds = [ind_eval("1.3.А", parse_num(ctx["raw"].get("i13A")), src_ok(ctx, "s13A")),
            ind_eval("1.3.Б", parse_num(ctx["raw"].get("i13B")), src_ok(ctx, "s13B")),
            ind_eval("1.3.В", parse_num(ctx["raw"].get("i13V")), src_ok(ctx, "s13V"))]
    res = metric_score(inds)
    res["indicators"] = inds
    return res

def sf_14(ctx):
    g = ind_eval("1.4.Г", parse_num(ctx["raw"].get("i14G")), src_ok(ctx, "s14G"))
    top = parse_num(ctx["raw"].get("i14G_top"))
    if not g["missing"] and top is not None and top > 70:
        i = CATEGORIES.index(g["cat"])
        if i < 4:
            g["cat"] = CATEGORIES[i + 1]
            g["score"] = CATEGORY_SCORES[g["cat"]]
            g["note"] = "Более 70% экспорта в одну страну — на одну категорию ниже"
    inds = [ind_eval("1.4.А", parse_num(ctx["raw"].get("i14A")), src_ok(ctx, "s14A")),
            ind_eval("1.4.Б", parse_num(ctx["raw"].get("i14B")), src_ok(ctx, "s14B")),
            ind_eval("1.4.В", parse_num(ctx["raw"].get("i14V")), src_ok(ctx, "s14V")), g]
    res = metric_score(inds)
    res["indicators"] = inds
    return res

def segments_merge(rows):
    """Объединение товарных групп в сегменты (1.5)."""
    merged = []
    keys = {}
    for i in range(len(rows)):
        r = rows[i]
        g = r.get("group") or "other"
        cg = COMMODITY.get(g)
        raw = cg["raw"] if cg is not None else None
        key = raw if raw is not None else "other#%d" % i
        label = cg["name"] if cg is not None else "Прочее"
        if g == "other" and r.get("name"):
            label = "Прочее: " + r["name"]
        rev = nz(r.get("rev"))
        gp = rev - nz(r.get("cogs"))
        if key in keys:
            m = merged[keys[key]]
            m["rev"] += rev
            m["gp"] += gp
            if label not in m["labels"]:
                m["labels"].append(label)
        else:
            keys[key] = len(merged)
            merged.append({"key": key, "labels": [label], "rev": rev, "gp": gp})
    return merged

def sf_15(ctx, series):
    rows = gtable(ctx, "seg15")
    ok = src_ok(ctx, "s15")
    segs = segments_merge(rows)
    tot = 0
    gp_tot = 0
    for s in segs:
        tot += s["rev"]
        gp_tot += s["gp"]
    nkey = None
    big = None
    force_b = None
    if len(segs) > 0 and tot > 0:
        nkey = 0
        best = None
        for s in segs:
            s["share"] = s["rev"] / tot * 100
            s["key_seg"] = s["share"] >= 10 and s["gp"] > 0
            if s["key_seg"]:
                nkey += 1
            if best is None or s["gp"] > best["gp"]:
                best = s
        if gp_tot > 0:
            big = best["gp"] / gp_tot * 100
        else:
            force_b = "Ca"
    a = ind_eval("1.5.А", nkey, ok)
    b = ind_eval("1.5.Б", big, ok, force_cat=force_b if nkey is not None else None,
                 note="Валовая прибыль всех сегментов не положительна" if force_b else None)
    inds = [a, b]
    res = metric_score(inds)
    res["indicators"] = inds
    res["segments"] = segs
    nneg = 0
    nyears = 0
    for r in series[:3]:
        nyears += 1
        if r["ebitda"] < 0:
            nneg += 1
    res["neg_years"] = nneg
    if nkey == 1 and ok:
        if nneg >= 2:
            apply_cap(res, 20, "Один сегмент и убытки", "Один ключевой сегмент и отрицательная EBITDA в двух и более из 3 лет — Ca (20)", exact=True)
        elif nneg == 1:
            apply_cap(res, 18, "Один сегмент и убыток", "Один ключевой сегмент и отрицательная EBITDA в одном из 3 лет — не лучше Caa (18)")
    return res

def garden_phase(kind, age):
    g = GARDEN[kind]
    if age < g["start"]:
        return "young", 0.0
    if age < g["full_from"]:
        if g["full_from"] == g["start"]:
            return "full", 1.0
        return "entering", 0.2 + 0.6 * (age - g["start"]) / float(g["full_from"] - g["start"])
    if age <= g["full_to"]:
        return "full", 1.0
    if age <= g["end"]:
        return "decline", 0.7
    return "old", 0.4

def garden_rows(ctx):
    out = []
    hy = ctx["harvest_year"]
    for r in gtable(ctx, "gardens"):
        kind = r.get("kind")
        if kind not in GARDEN or not is_num(r.get("year")) or not is_num(r.get("area")) or r["area"] <= 0 or hy is None:
            continue
        g = GARDEN[kind]
        age = hy - int(r["year"])
        ph, coef = garden_phase(kind, age)
        d = dict(r)
        d["age"] = age
        d["phase"] = ph
        d["coef"] = coef
        d["norm"] = []
        for k in range(3):
            a = age - k
            if a < 0:
                d["norm"].append(0.0)
            else:
                d["norm"].append(garden_phase(kind, a)[1] * r["area"] * g["yield"])
        # фактор приведённой площади (1.6)
        if ph == "full":
            d["nat_k"] = 5 if g["intensive"] else 2
        else:
            d["nat_k"] = 1
        # право на землю (2.1.Г″)
        remaining = g["end"] - age
        if remaining < 0:
            remaining = 0
        need = min(remaining, 10)
        if r.get("land") == "own":
            d["land_ok"] = True
        elif r.get("land") == "lease" and is_num(r.get("lease_end")):
            d["land_ok"] = (r["lease_end"] - hy) >= need
        else:
            d["land_ok"] = False
        d["need_years"] = need
        if is_num(r.get("trees")) and r["trees"] > 0:
            d["loss"] = (nz(r.get("lost")) + nz(r.get("sick"))) / r["trees"] * 100
        else:
            d["loss"] = None
        out.append(d)
    return out

def garden_calc(ctx):
    rows = garden_rows(ctx)
    ok = src_ok(ctx, "s21g")
    res = {"rows": rows}
    area = 0
    a_full = 0
    a_land = 0
    loss_a = 0
    loss_s = 0
    flags = {"drip": 0, "net": 0, "frost": 0, "cert": 0}
    for r in rows:
        area += r["area"]
        if r["phase"] == "full":
            a_full += r["area"]
        if r["land_ok"]:
            a_land += r["area"]
        if r["loss"] is not None:
            loss_a += r["area"]
            loss_s += r["area"] * r["loss"]
        for k in flags:
            if r.get(k):
                flags[k] += r["area"]
    res["area"] = area
    harv = [gnum(ctx, "g_harv_0"), gnum(ctx, "g_harv_1"), gnum(ctx, "g_harv_2")]
    norms = [0.0, 0.0, 0.0]
    for r in rows:
        for k in range(3):
            norms[k] += r["norm"][k]
    res["norms"] = norms
    res["harvests"] = harv
    if area <= 0:
        inds = [ind_eval(c, None, ok) for c in ["2.1.А″", "2.1.Б″", "2.1.В″", "2.1.Г″", "2.1.Д″"]]
        res["indicators"] = inds
        res["points"] = None
        return res
    a = a_full / area * 100
    s_act = 0
    s_norm = 0
    have_norm = False
    missing_h = False
    for k in range(3):
        if norms[k] > 0:
            have_norm = True
            if harv[k] is None:
                missing_h = True
            else:
                s_act += harv[k]
                s_norm += norms[k]
    if not have_norm:
        b = ind_eval("2.1.Б″", None, ok, na=True)
        b["note"] = "Плодоносящих насаждений нет — индикатор не применяется"
    elif missing_h or s_norm <= 0:
        b = ind_eval("2.1.Б″", None, ok)
    else:
        b = ind_eval("2.1.Б″", s_act / s_norm * 100, ok)
    res["yield_act"] = s_act
    res["yield_norm"] = s_norm
    v = ind_eval("2.1.В″", loss_s / loss_a if loss_a > 0 else None, ok)
    g = ind_eval("2.1.Г″", a_land / area * 100, ok)
    pts = 0
    pl = []
    for k in ["drip", "net", "frost", "cert"]:
        on = flags[k] / area >= 0.5
        pl.append({"key": k, "share": flags[k] / area * 100, "ok": on})
        if on:
            pts += 1
    hsum = 0
    hn = 0
    for h in harv:
        if h is not None:
            hsum += h
            hn += 1
    cold = gnum(ctx, "g_cold")
    cold_ok = cold is not None and hn > 0 and hsum / hn > 0 and cold >= 0.3 * hsum / hn
    pl.append({"key": "cold", "share": (cold / (hsum / hn) * 100) if (cold is not None and hn > 0 and hsum > 0) else None, "ok": cold_ok})
    if cold_ok:
        pts += 1
    res["points_list"] = pl
    res["points"] = pts
    d = ind_eval("2.1.Д″", pts, ok)
    res["indicators"] = [ind_eval("2.1.А″", a, ok), b, v, g, d]
    return res

def nat_value(ctx, c):
    """Натуральный объём подсектора в единицах его шкалы; None — нет данных."""
    if c == "DAI":
        m = gnum(ctx, "nat_DAI_milk")
        return m / 365.0 if m is not None else None
    if c == "MEA":
        a = gnum(ctx, "nat_MEA_meat")
        b = gnum(ctx, "nat_MEA_eggs")
        if a is None and b is None:
            return None
        return nz(a) + nz(b) * 60
    if c == "CRP":
        an = gnum(ctx, "crp_area_annual") if ctx["annual"] else None
        gr = gnum(ctx, "crp_area_green") if ctx["annual"] else None
        rows = garden_rows(ctx) if ctx["garden"] else []
        if an is None and gr is None and len(rows) == 0:
            return None
        t = nz(an) + nz(gr) * 40
        for r in rows:
            t += r["area"] * r["nat_k"]
        return t
    if c == "OIL":
        a = gnum(ctx, "nat_OIL_seed")
        b = gnum(ctx, "nat_OIL_oil")
        if a is None and b is None:
            return None
        return nz(a) + nz(b) * 2.5
    if c == "SUG":
        a = gnum(ctx, "nat_SUG_beet")
        b = gnum(ctx, "nat_SUG_raw")
        if a is None and b is None:
            return None
        return nz(a) + nz(b) * 8
    if c == "FRU":
        a = gnum(ctx, "nat_FRU_fresh")
        b = gnum(ctx, "nat_FRU_dried")
        k = gnum(ctx, "nat_FRU_kernel")
        if a is None and b is None and k is None:
            return None
        return nz(a) + nz(b) * 4 + nz(k) * 2
    if c == "PRM":
        t = 0
        anyv = False
        for l in LIVESTOCK:
            v = gnum(ctx, l["key"])
            if v is not None:
                anyv = True
                t += v * l["k"]
        return t if anyv else None
    key = {"FLR": "nat_FLR", "FED": "nat_FED", "CTN": "nat_CTN", "API": "nat_API", "FSH": "nat_FSH"}.get(c)
    return gnum(ctx, key) if key else None

def sf_16(ctx):
    parts = []
    tot = 0
    all_def = True
    for c in ctx["segs"]:
        v = nat_value(ctx, c)
        b = ctx["settings"]["nat"][c]
        p = quant_result("1.6", "nat", v, b, "higher", unit=SUBSECTORS[c]["nat"]["unit"])
        p["sub"] = c
        p["w"] = ctx["seg_w"][c]
        parts.append(p)
        tot += p["w"] * p["score"]
        if not p["all_default"]:
            all_def = False
    if len(parts) == 1:
        return parts[0]
    sc = q(tot, 2)
    return {"code": "1.6", "metric": "nat", "value": None, "unit": "", "raw": sc, "score": sc, "cat": category_for_score(sc),
            "caps": [], "all_default": all_def, "parts": parts, "note": "Взвешенный по выручке балл сегментов"}

# ── Блок 2 ───────────────────────────────────────────────────────────────

def b21_na(ctx, c):
    if c in ("DAI", "SUG"):
        return True
    if c == "MEA" and not gbool(ctx, "mea_poultry"):
        return True
    if c == "FRU":
        v = parse_num(ctx["raw"].get("fru_fresh_share"))
        if v is not None and v > 50:
            return True
    return False

def sf_21_sub(ctx, c):
    need = gnum(ctx, "r21_need_" + c)
    own = gnum(ctx, "r21_own_" + c)
    con = gnum(ctx, "r21_contr_" + c)
    a = None
    if need is not None and need > 0 and (own is not None or con is not None):
        a = (nz(own) + 0.5 * nz(con)) / need * 100
    inds = [ind_eval("2.1.А", a, src_ok(ctx, "s21A_" + c)),
            ind_eval("2.1.Б", parse_num(ctx["raw"].get("i21B_" + c)), src_ok(ctx, "s21B_" + c), na=b21_na(ctx, c)),
            ind_eval("2.1.В", parse_num(ctx["raw"].get("i21V_" + c)), src_ok(ctx, "s21V_" + c)),
            ind_eval("2.1.Г", parse_num(ctx["raw"].get("i21G_" + c)), src_ok(ctx, "s21G_" + c))]
    res = metric_score(inds)
    res["indicators"] = inds
    res["label"] = SUBSECTORS[c]["name"]
    res["sub"] = c
    return res

def sf_21_crp_annual(ctx):
    area = nz(gnum(ctx, "crp_area_annual")) + nz(gnum(ctx, "crp_area_green"))
    sec = gnum(ctx, "crp_area_secure")
    a = sec / area * 100 if (sec is not None and area > 0) else None
    inds = [ind_eval("2.1.А′", a, src_ok(ctx, "s21Ap")),
            ind_eval("2.1.Б′", parse_num(ctx["raw"].get("i21Bp")), src_ok(ctx, "s21Bp")),
            ind_eval("2.1.В′", parse_num(ctx["raw"].get("i21Vp")), src_ok(ctx, "s21Vp")),
            ind_eval("2.1.Г′", parse_num(ctx["raw"].get("i21Gp")), src_ok(ctx, "s21Gp"))]
    res = metric_score(inds)
    res["indicators"] = inds
    res["label"] = "Однолетние культуры (2.1.1)"
    return res

def sf_21_crp(ctx):
    p = ctx["crp_p"] / 100.0
    parts = []
    if p >= 0.15 and p <= 0.85:
        wa = 1 - p
        wg = p
    elif p > 0.5:
        wa = 0
        wg = 1
    else:
        wa = 1
        wg = 0
    if wa > 0:
        an = sf_21_crp_annual(ctx)
        an["w"] = wa
        parts.append(an)
    if wg > 0:
        gc = garden_calc(ctx)
        gr = metric_score(gc["indicators"])
        gr["indicators"] = gc["indicators"]
        gr["label"] = "Многолетние насаждения (2.1.2)"
        gr["garden"] = gc
        gr["w"] = wg
        parts.append(gr)
    s = 0
    alld = True
    for x in parts:
        s += x["w"] * x["score"]
        if not x["all_default"]:
            alld = False
    sc = q(s, 2)
    return {"score": sc, "raw": sc, "parts": parts, "all_default": alld, "caps": [], "label": SUBSECTORS["CRP"]["name"], "sub": "CRP"}

def sf_21(ctx):
    parts = []
    for c in ctx["segs"]:
        if c == "CRP":
            r = sf_21_crp(ctx)
        else:
            r = sf_21_sub(ctx, c)
        r["seg_w"] = ctx["seg_w"][c]
        parts.append(r)
    if len(parts) == 1:
        r = parts[0]
        if "indicators" in r:
            return r
        return r
    s = 0
    alld = True
    for x in parts:
        s += x["seg_w"] * x["score"]
        if not x["all_default"]:
            alld = False
    sc = q(s, 2)
    return {"score": sc, "raw": sc, "segments": parts, "all_default": alld, "caps": [], "note": "Взвешенный по выручке балл сегментов"}

def seasonality_rules(ctx):
    base = IND["2.2.В"]
    common = _L(*SEASONALITY_SCALES["I"])
    g3 = _L(*SEASONALITY_SCALES["III"])
    w = ctx["g3"]
    if w <= 0:
        return common
    if w >= 1:
        return g3
    return blend_rules(g3, common, w)

def sf_22(ctx):
    pa = 0
    if gbool(ctx, "f22A_iso"):
        pa += 2
    for k in ["f22A_haccp", "f22A_export", "f22A_halal", "f22A_lab"]:
        if gbool(ctx, k):
            pa += 1
    qs = [gnum(ctx, "q_rev_%d" % i) for i in range(1, 5)]
    v = None
    if None not in qs:
        t = qs[0] + qs[1] + qs[2] + qs[3]
        if t > 0:
            v = max(qs) / t * 100
    pg = 0
    glist = []
    pw = parse_num(ctx["raw"].get("i22G_power"))
    glist.append({"key": "power", "ok": pw is not None and pw >= 50})
    if ctx["main"] == "CRP":
        wv = parse_num(ctx["raw"].get("i22G_water_crp"))
        glist.append({"key": "water", "ok": wv is not None and wv >= 80})
    else:
        glist.append({"key": "water", "ok": gbool(ctx, "f22G_water")})
    glist.append({"key": "prop", "ok": gbool(ctx, "f22G_prop")})
    bi = parse_num(ctx["raw"].get("i22G_bio"))
    glist.append({"key": "bio", "ok": bi is not None and bi >= 50})
    if ctx["prot"] == "storage":
        stv = parse_num(ctx["raw"].get("i22G_storage"))
        glist.append({"key": "storage", "ok": stv is not None and stv >= 2})
    else:
        glist.append({"key": "vet", "ok": gbool(ctx, "f22G_vet")})
    for x in glist:
        if x["ok"]:
            pg += 1
    inds = [ind_eval("2.2.А", pa, src_ok(ctx, "s22A")),
            ind_eval("2.2.Б", parse_num(ctx["raw"].get("i22B")), src_ok(ctx, "s22B")),
            ind_eval("2.2.В", v, src_ok(ctx, "s22V"), rules=seasonality_rules(ctx)),
            ind_eval("2.2.Г", pg, src_ok(ctx, "s22G"))]
    res = metric_score(inds)
    res["indicators"] = inds
    res["g_points"] = glist
    res["season_rules"] = seasonality_rules(ctx)
    if gbool(ctx, "f22_quar"):
        apply_cap(res, 18, "Карантин или запрет", "На дату оценки действует карантин, запрет экспорта или приостановка деятельности — не лучше Caa (18)")
    return res

def equipment_age(ctx):
    rows = []
    for r in gtable(ctx, "equip"):
        if is_num(r.get("cost")) and r["cost"] > 0 and is_num(r.get("year")):
            rows.append(r)
    ry = ctx["report_year"]
    if len(rows) == 0 or ry is None:
        return None, []
    rows.sort(key=lambda x: -x["cost"])
    tot = 0
    for r in rows:
        tot += r["cost"]
    acc = 0
    chosen = []
    for r in rows:
        if acc >= 0.8 * tot:
            break
        chosen.append(r)
        acc += r["cost"]
    s = 0
    w = 0
    for r in chosen:
        age = ry - r["year"]
        if age < 0:
            age = 0
        s += age * r["cost"]
        w += r["cost"]
    return (s / w if w > 0 else None), chosen

def sf_23(ctx):
    if gbool(ctx, "f23_reval"):
        rp = gnum(ctx, "i23_repl")
        rs = gnum(ctx, "i23_resid")
        wear = (1 - rs / rp) * 100 if (rp is not None and rp > 0 and rs is not None) else None
    else:
        c = gnum(ctx, "i23_cost")
        d = gnum(ctx, "i23_accdep")
        wear = d / c * 100 if (c is not None and c > 0 and d is not None) else None
    cx = gnum(ctx, "i23_capex3")
    dp = gnum(ctx, "i23_dep3")
    ren = cx / dp * 100 if (cx is not None and dp is not None and dp > 0) else None
    age, chosen = equipment_age(ctx)
    na_g = ctx["main"] in ("CRP", "PRM", "API")
    dn = parse_num(ctx["raw"].get("i23_down"))
    pl = parse_num(ctx["raw"].get("i23_plan"))
    dt = dn / pl * 100 if (dn is not None and pl is not None and pl > 0) else None
    inds = [ind_eval("2.3.А", wear, src_ok(ctx, "s23A")),
            ind_eval("2.3.Б", ren, src_ok(ctx, "s23B")),
            ind_eval("2.3.В", age, src_ok(ctx, "s23V")),
            ind_eval("2.3.Г", dt, src_ok(ctx, "s23G"), na=na_g)]
    res = metric_score(inds)
    res["indicators"] = inds
    res["equip_main"] = len(chosen)
    if wear is not None and ren is not None and src_ok(ctx, "s23A") and src_ok(ctx, "s23B") and wear > 70 and ren < 50:
        apply_cap(res, 15, "Изношенное оборудование без обновления", "Износ более 70% и обновление менее 50% амортизации — не лучше B (15)")
    return res

# ── Блок 3 ───────────────────────────────────────────────────────────────

def margin_bounds(ctx):
    st = ctx["settings"]["margin"]
    ms = ctx["settings"]["margin_sub"]
    if ctx["group"] == "MIX":
        own = False
        for c in SEGMENT_SUBS:
            if ms[c] is not None and ctx["shares"][c] > 0:
                own = True
        out = []
        if not own:
            for i in range(9):
                out.append(ctx["gshare"]["I"] * st["I"][i] + ctx["gshare"]["II"] * st["II"][i] + ctx["gshare"]["III"] * st["III"][i])
            return out
        # у сегментов есть свои пороги маржи из настроек: граница = Σ доля × граница подсектора
        for i in range(9):
            t = 0
            for c in SEGMENT_SUBS:
                sh = ctx["shares"][c] / 100.0
                if sh > 0:
                    b = ms[c] if ms[c] is not None else st[sub_group(ctx, c)]
                    t += sh * b[i]
            out.append(t)
        return out
    if ctx["main"] in ms and ms[ctx["main"]] is not None:
        return list(ms[ctx["main"]])
    g = ctx["group"] if ctx["group"] in st else "II"
    return list(st[g])

def avg_margin(series):
    if len(series) == 0:
        return None, None
    if len(series) >= 3:
        return (series[0]["margin"] + series[1]["margin"] + series[2]["margin"]) / 3.0, "avg3"
    m = series[0]["margin"]
    for r in series:
        if r["margin"] < m:
            m = r["margin"]
    return m, "min"

def sf_31(ctx, series):
    m, how = avg_margin(series)
    res = quant_result("3.1", "margin", m, margin_bounds(ctx), "higher")
    res["how"] = how
    res["years"] = len(series)
    return res

def sf_32(ctx, series):
    n = len(series)
    if n < 2:
        res = quant_result("3.2", "mpm", None, ctx["settings"]["bounds"]["mpm"], "lower")
        res["note"] = "Ряд маржи из одного года — подфактор не рассчитывается" if n == 1 else None
        res["years"] = n
        return res
    ser = series[:5]
    chrono = []
    for i in range(len(ser) - 1, -1, -1):
        chrono.append(ser[i]["margin"])
    avg = 0
    for x in chrono:
        avg += x
    avg = avg / len(chrono)
    drop = 0
    for i in range(len(chrono) - 1):
        d = chrono[i] - chrono[i + 1]
        if d > drop:
            drop = d
    if avg <= 0:
        res = quant_result("3.2", "mpm", None, ctx["settings"]["bounds"]["mpm"], "lower", special=20.5)
        res["note"] = "Средняя маржа ≤ 0 — 20,5"
        res["value"] = None
    else:
        mpm = drop / abs(avg) * 100
        res = quant_result("3.2", "mpm", mpm, ctx["settings"]["bounds"]["mpm"], "lower")
    res["years"] = len(chrono)
    res["max_drop"] = drop
    res["avg"] = avg
    if len(chrono) == 3:
        apply_cap(res, 4.5, "Короткий ряд (3 года)", "Ряд из 3 лет — не лучше A (4,5)")
    elif len(chrono) == 2:
        apply_cap(res, 7.5, "Короткий ряд (2 года)", "Ряд из 2 лет — не лучше Baa (7,5); расчёт неполный")
    return res

# ── Блок 5 ───────────────────────────────────────────────────────────────

def equity_adjusted(ctx):
    eq = gnum(ctx, "equity_end")
    if eq is None:
        return None, 0
    cut = 0
    if ctx["garden"]:
        bk = gnum(ctx, "garden_book")
        vl = gnum(ctx, "garden_value")
        if bk is not None and vl is not None and bk > vl:
            cut = bk - vl
    return eq - cut, cut

def distributions(ctx):
    dist = 0
    npr = 0
    years = 0
    for y in range(3):
        n = gnum(ctx, "np_%d" % y)
        d = nz(gnum(ctx, "div_%d" % y)) + nz(gnum(ctx, "buyback_%d" % y)) + nz(gnum(ctx, "ownloan_%d" % y))
        if n is not None:
            years += 1
            npr += n
            dist += d
    return dist, npr, years

def sf_51(ctx):
    pa = 0
    for i in range(1, 7):
        if gbool(ctx, "f51_%d" % i):
            pa += 1
    eq, cut = equity_adjusted(ctx)
    l1 = gnum(ctx, "i51_loans")
    l2 = gnum(ctx, "i51_recv")
    l3 = gnum(ctx, "i51_guar")
    expo = None
    if l1 is not None or l2 is not None or l3 is not None:
        expo = nz(l1) + nz(l2) + nz(l3)
    sb = src_ok(ctx, "s51B")
    if eq is None:
        b = ind_eval("5.1.Б", None, sb)
    elif eq <= 0:
        b = ind_eval("5.1.Б", None, sb, force_cat="Ca", note="Собственный капитал ≤ 0")
    elif expo is None:
        b = ind_eval("5.1.Б", None, sb)
    else:
        b = ind_eval("5.1.Б", expo / eq * 100, sb)
    dist, npr, years = distributions(ctx)
    sv = src_ok(ctx, "s51V")
    if years == 0:
        v = ind_eval("5.1.В", None, sv)
    elif npr <= 0:
        if dist > 0:
            v = ind_eval("5.1.В", None, sv, force_cat="Ca", note="Чистая прибыль за 3 года ≤ 0, выплаты были")
        else:
            v = ind_eval("5.1.В", None, sv, force_cat="Ba", note="Чистая прибыль за 3 года ≤ 0, выплат не было")
    else:
        v = ind_eval("5.1.В", dist / npr * 100, sv)
    inds = [ind_eval("5.1.А", pa, src_ok(ctx, "s51A")), b, v]
    res = metric_score(inds)
    res["indicators"] = inds
    res["equity_cut"] = cut
    if gbool(ctx, "in_group") and not gbool(ctx, "consolidated"):
        apply_cap(res, 12, "Нет отчётности группы", "Компания входит в группу без консолидированной отчётности — не лучше Ba (12)")
    und = parse_num(ctx["raw"].get("i_undisclosed"))
    if und is not None and und > 0 and und <= 25:
        apply_cap(res, 15, "Бенефициары раскрыты не полностью", "Нераскрытая часть капитала %s%% (не больше 25%%) — не лучше B (15)" % fmt_num(und, 1))
    return res

def integrity_tests(ctx):
    out = []
    a = gnum(ctx, "assets_end")
    l = gnum(ctx, "liabeq_end")
    if a is not None and l is not None and a > 0:
        out.append({"id": 1, "result": "pass" if abs(a - l) <= 0.005 * a else "fail", "auto": True, "diff": abs(a - l) / a * 100})
    else:
        out.append({"id": 1, "result": "", "auto": True, "diff": None})
    cf = gnum(ctx, "cfs_change")
    ce = gnum(ctx, "cash_end")
    cb = gnum(ctx, "cash_begin")
    if cf is not None and ce is not None and cb is not None:
        dlt = ce - cb
        base = max(abs(dlt), abs(cf))
        diff = abs(cf - dlt)
        okk = diff <= 0.01 * base or diff <= 1
        out.append({"id": 2, "result": "pass" if okk else "fail", "auto": True, "diff": (diff / base * 100) if base > 0 else 0})
    else:
        out.append({"id": 2, "result": "", "auto": True, "diff": None})
    for t in INTEGRITY_TESTS:
        if not t["auto"]:
            out.append({"id": t["id"], "result": gstr(ctx, "t%d" % t["id"]), "auto": False, "diff": None})
    return out

def sf_52(ctx, tests):
    std = gstr(ctx, "r52_std")
    aud = gstr(ctx, "r52_auditor")
    yrs = parse_num(ctx["raw"].get("r52_years"))
    if yrs is None:
        yrs = 0
    op = gstr(ctx, "r52_opinion")
    days = parse_num(ctx["raw"].get("r52_days"))
    forms = gbool(ctx, "r52_forms")
    diff = parse_num(ctx["raw"].get("r52_diff"))
    audited = aud in ("licensed", "ifac") and yrs >= 1
    cat = None
    why = ""
    if std == "none":
        cat = "Ca"
        why = "Отчётность не предоставлена"
    elif diff is not None and diff > 10:
        cat = "Ca"
        why = "Налоговая и представленная отчётность расходятся по выручке более чем на 10%"
    elif std == "" or aud == "":
        cat = None
    elif op in ("adverse", "disclaim") and audited:
        cat = "Caa"
        why = "Отрицательное мнение аудитора или отказ от мнения"
    elif not forms:
        cat = "Caa"
        why = "Нет одной из форм 1–3"
    elif not audited:
        cat = "B"
        why = "Аудита нет; формы 1–3 полные"
    elif op == "":
        cat = None
    else:
        ifrs = std == "ifrs"
        unmod = op == "unmod"
        d120 = days is not None and days <= 120
        d150 = days is not None and days <= 150
        if ifrs and aud == "ifac" and yrs >= 5 and unmod and d120:
            cat = "Aaa"
        elif ifrs and aud == "ifac" and yrs >= 3 and unmod and d120:
            cat = "Aa"
        elif ifrs and ((aud == "ifac" and yrs >= 1) or (aud == "licensed" and yrs >= 3)) and unmod and d150:
            cat = "A"
        elif std in ("ifrs", "ifrs_sme") and unmod:
            cat = "Baa"
        elif op in ("unmod", "qual"):
            cat = "Ba"
        else:
            cat = "B"
        why = "Лучшая категория, все условия которой выполнены"
    fails = 0
    for t in tests:
        if t["result"] == "fail":
            fails += 1
    if cat is None:
        res = {"score": DEFAULT_SCORE, "raw": DEFAULT_SCORE, "cat": None, "all_default": True, "caps": [], "why": "Данных о стандарте и аудиторе нет"}
    else:
        res = {"score": CATEGORY_SCORES[cat], "raw": CATEGORY_SCORES[cat], "cat": cat, "all_default": False, "caps": [], "why": why}
    res["fails"] = fails
    res["tests"] = tests
    if cat is not None and not audited and std != "none":
        apply_cap(res, 15, "Нет аудита", "Без аудированной отчётности — не лучше B (15)")
    if fails >= 3:
        apply_cap(res, 18, "Провалены тесты целостности", "Провалено %d теста(ов) целостности — не лучше Caa (18)" % fails)
    elif fails == 2:
        apply_cap(res, 15, "Провалены тесты целостности", "Провалено 2 теста целостности — не лучше B (15)")
    return res

def stop_factors(ctx):
    out = []
    if gbool(ctx, "f53_list"):
        out.append("Компания, бенефициар, руководитель или главный бухгалтер в санкционных перечнях ГСФР или Совета Безопасности ООН")
    und = parse_num(ctx["raw"].get("i_undisclosed"))
    if gbool(ctx, "f53_refuse") or (und is not None and und > 25):
        out.append("Конечные бенефициары не раскрыты (отказ или нераскрытая часть более 25% капитала)")
    if gbool(ctx, "f53_convict"):
        out.append("За 5 лет вступил в силу приговор или решение суда за легализацию доходов или финансирование терроризма")
    return out

def sf_53(ctx):
    pts = 0
    pl = []
    a1 = gbool(ctx, "f53_benef")
    a2 = not gbool(ctx, "f53_sanct") and not gbool(ctx, "f53_bank_sanct")
    cash = parse_num(ctx["raw"].get("i53_cash"))
    a3 = cash is not None and cash <= 20
    hr = parse_num(ctx["raw"].get("i53_hr"))
    a4 = hr is not None and (hr == 0 or (hr <= 5 and gbool(ctx, "f53_hr_docs")))
    a5 = not gbool(ctx, "f53_viol")
    for k, okk in (("benef", a1), ("sanct", a2), ("cash", a3), ("hr", a4), ("viol", a5)):
        pl.append({"key": k, "ok": okk})
        if okk:
            pts += 1
    ok = src_ok(ctx, "s53")
    inds = [ind_eval("5.3.А", pts, ok)]
    res = metric_score(inds)
    res["indicators"] = inds
    res["points_list"] = pl
    if gbool(ctx, "f53_sanct"):
        apply_cap(res, 20, "Санкции США, ЕС, Великобритании", "Компания, бенефициар или руководитель под санкциями — 5.3 = Ca (20); итоговая оценка не выше B1", exact=True)
    elif gbool(ctx, "f53_crim"):
        apply_cap(res, 18, "Уголовное дело о легализации", "Возбуждено уголовное дело — 5.3 не лучше Caa (18); −1 ступень итоговой оценки")
    return res

