def restructurings(ctx):
    rows = gtable(ctx, "restr")
    ev = ctx["eval_date"]
    items = []
    for i in range(len(rows)):
        r = rows[i]
        d = parse_date(r.get("date"))
        it = {"n": i + 1, "date": r.get("date") or "", "reason": r.get("reason") or "", "months": None, "in5": True, "in36": True, "reasons": []}
        if d is not None and ev is not None:
            m = months_between(d, ev)
            it["months"] = m
            it["in5"] = m < 60
            it["in36"] = m < 36
        else:
            it["reasons"].append("дата не указана — считается в пределах периода")
        below = False
        if is_num(r.get("new_rate")) and is_num(r.get("old_rate")) and is_num(r.get("nbkr_rate")) and not r.get("subsidy"):
            below = r["new_rate"] < r["old_rate"] - 3 and r["new_rate"] < r["nbkr_rate"]
        t = None
        if r.get("writeoff"):
            t = 4
            it["reasons"].append("списание или уменьшение долга или процентов")
        if r.get("capitalized"):
            t = 4
            it["reasons"].append("капитализация процентов без процентов на них")
        if below:
            t = 4
            it["reasons"].append("ставка ниже рыночной")
        if r.get("overdue30"):
            t = 4
            it["reasons"].append("просрочка более 30 дней после реструктуризации")
        if t is None:
            if not r.get("docs"):
                t = 3
                it["reasons"].append("вид не подтверждён документами")
            elif it["reason"] == "system":
                t = 1
            elif it["reason"] == "technical":
                t = 2
            else:
                t = 3
        it["type"] = t
        it["sort"] = d if d is not None else (0, 0, 0)
        items.append(it)
    # вторая вынужденная реструктуризация за 36 месяцев → вид 4
    order = sorted(range(len(items)), key=lambda k: (items[k]["sort"], items[k]["n"]))
    prev3 = []
    for k in order:
        it = items[k]
        if it["type"] == 3:
            d = parse_date(it["date"])
            for pd in prev3:
                if d is not None and pd is not None and months_between(pd, d) < 36:
                    it["type"] = 4
                    it["reasons"].append("вторая вынужденная реструктуризация за 36 месяцев")
                    break
            if it["type"] == 3:
                prev3.append(d)
    for it in items:
        del it["sort"]
    return items

def credit_events(ctx, restr):
    rep = gstr(ctx, "r61_report")
    m36 = parse_num(ctx["raw"].get("i61_max36"))
    m5 = parse_num(ctx["raw"].get("i61_max5"))
    reasons = []
    if m36 is not None and m36 > 90:
        reasons.append("просрочка более 90 дней за 36 месяцев")
    elif m5 is not None and m5 > 90:
        reasons.append("просрочка более 90 дней за 5 лет")
    if gbool(ctx, "f61_writeoff"):
        reasons.append("списание долга кредитором")
    if gbool(ctx, "f61_court"):
        reasons.append("взыскание долга по решению суда")
    if gbool(ctx, "f61_bankrupt"):
        reasons.append("процедура банкротства, санации или ликвидации")
    t3 = False
    for it in restr:
        if it["type"] == 4 and it["in5"]:
            reasons.append("реструктуризация, приравненная к дефолту (№%d)" % it["n"])
        if it["type"] == 3 and it["in36"]:
            t3 = True
    return {"default": len(reasons) > 0, "default_reasons": reasons, "type3": t3, "refused": rep == "refused", "report": rep}

def sf_61(ctx, ev):
    rep = ev["report"]
    b = ctx["settings"]["bounds"]["overdue"]
    if ev["default"]:
        res = quant_result("6.1", "overdue", parse_num(ctx["raw"].get("i61_max36")), b, "lower", strict=True, special=20)
        res["caps"].append({"name": "Дефолт", "text": "Дефолт за 5 лет (%s) — 6.1 = 20, −2 ступени, итог не лучше B1" % "; ".join(ev["default_reasons"]), "level": 20, "exact": True})
        return res
    if rep == "refused":
        res = quant_result("6.1", "overdue", None, b, "lower", special=15)
        res["caps"].append({"name": "Отказ в согласии", "text": "Компания отказала в согласии на запрос бюро — 15 баллов и −1 ступень", "level": 15, "exact": True})
        return res
    if rep != "yes":
        res = quant_result("6.1", "overdue", None, b, "lower")
        res["note"] = "Отчёт бюро не предоставлен — 12 баллов (правило информационного дефицита)"
        return res
    m36 = parse_num(ctx["raw"].get("i61_max36"))
    if m36 is None:
        m36 = 0
    res = quant_result("6.1", "overdue", m36, b, "lower", strict=True)
    if ev["type3"]:
        apply_cap(res, 10.5, "Вынужденная реструктуризация", "Реструктуризация вида 3 за 36 месяцев — не лучше 10,5 и −1 ступень")
    cur = parse_num(ctx["raw"].get("i61_current"))
    if cur is not None and cur > 30:
        apply_cap(res, 13.5, "Текущая просрочка", "Текущая просрочка более 30 дней — не лучше 13,5")
    hist = parse_num(ctx["raw"].get("i63A"))
    if hist is not None and hist < 1:
        apply_cap(res, 12, "Короткая история", "Кредитная история короче 12 месяцев — не лучше 12")
    return res

def sf_62(ctx):
    b = ctx["settings"]["bounds"]["payables"]
    if gbool(ctx, "f62_noaging"):
        res = quant_result("6.2", "payables", None, b, "lower")
        res["note"] = "Аналитики по срокам нет — 12 баллов (правило информационного дефицита)"
        return res
    tot = None
    for k in ["p62_sup", "p62_tax", "p62_soc", "p62_wage", "p62_oth"]:
        v = gnum(ctx, k)
        if v is not None:
            tot = nz(tot) + v
    ov = gnum(ctx, "i62_overdue")
    if tot is None:
        res = quant_result("6.2", "payables", None, b, "lower")
    elif tot <= 0:
        res = quant_result("6.2", "payables", None, b, "lower", special=0.5)
        res["note"] = "Кредиторской задолженности нет — 0,5"
    elif ov is None:
        res = quant_result("6.2", "payables", None, b, "lower")
    else:
        res = quant_result("6.2", "payables", ov / tot * 100, b, "lower")
    res["total"] = tot
    if gbool(ctx, "f62_tax90"):
        apply_cap(res, 13.5, "Налоги просрочены более 90 дней", "Налоги или взносы просрочены более 90 дней — не лучше 13,5")
    return res

def sf_63(ctx, ev):
    inds = [ind_eval("6.3.А", parse_num(ctx["raw"].get("i63A")), src_ok(ctx, "s63A")),
            ind_eval("6.3.Б", parse_num(ctx["raw"].get("i63B")), src_ok(ctx, "s63B")),
            ind_eval("6.3.В", parse_num(ctx["raw"].get("i63V")), src_ok(ctx, "s63V")),
            ind_eval("6.3.Г", parse_num(ctx["raw"].get("i63G")), src_ok(ctx, "s63G"))]
    res = metric_score(inds)
    res["indicators"] = inds
    if ev["default"]:
        apply_cap(res, 18, "Дефолт за 5 лет", "Дефолт или судебное взыскание за 5 лет — не лучше Caa (18)")
    if gbool(ctx, "f63_owners90"):
        apply_cap(res, 15, "Просрочка владельцев", "У ключевых владельцев просрочка свыше 90 дней за 36 месяцев — не лучше B (15)")
    return res

