def tax_fact(ctx):
    if gbool(ctx, "tax_exempt"):
        return 0, "exempt"
    t = gnum(ctx, "tax_cfs")
    if t is not None:
        return t, "cfs"
    t = gnum(ctx, "tax_pl")
    if t is not None:
        return t, "pl"
    p = gnum(ctx, "pbt")
    if p is not None:
        return 0.1 * max(p, 0), "pbt10"
    return 0, "none"

def tax_rate_forecast(ctx, tax):
    if gbool(ctx, "tax_exempt"):
        return 0
    p = gnum(ctx, "pbt")
    if p is not None and p > 0:
        r = tax / p
        return max(0, min(0.1, r))
    return 0.1

def debt_data(ctx):
    st = nz(gnum(ctx, "debt_st"))
    bal = st + nz(gnum(ctx, "debt_ltb")) + nz(gnum(ctx, "debt_lto")) + nz(gnum(ctx, "debt_lease"))
    begin = gnum(ctx, "debt_begin")
    if begin is None:
        begin = bal
    d = {"bal": bal, "st": st, "begin": begin, "cash": nz(gnum(ctx, "cash_end")), "undrawn": nz(gnum(ctx, "undrawn")),
         "oth_st": nz(gnum(ctx, "oth_st")), "adv": nz(gnum(ctx, "adv_refund")), "mode": "bal", "ded": 0}
    qd = [gnum(ctx, "q_debt_%d" % k) for k in (1, 2, 3)]
    qs = [gnum(ctx, "q_st_%d" % k) for k in (1, 2, 3)]
    qi = [gnum(ctx, "q_inv_%d" % k) for k in (0, 1, 2, 3)]
    seas = ctx["seasonal"]
    qconf = seas and gbool(ctx, "f_q_conf") and None not in qd
    inv_ok = seas and gbool(ctx, "f_inv_doc") and gbool(ctx, "f_inv_ins") and gbool(ctx, "f_inv_12m")
    d["seasonal"] = seas
    d["qconf"] = qconf
    d["inv_ok"] = inv_ok
    dd = [bal, qd[0], qd[1], qd[2]]
    ss = [st, qs[0], qs[1], qs[2]]

    def ded(k):
        if not inv_ok or qi[k] is None or qi[k] <= 0:
            return 0
        s = ss[k] if ss[k] is not None else 0
        return min(0.7 * qi[k], max(s, 0))
    if qconf:
        d43 = (dd[0] + dd[1] + dd[2] + dd[3]) / 4.0
        inv_all = inv_ok and qi[0] is not None and qi[1] is not None and qi[2] is not None and qi[3] is not None
        if inv_all:
            t = 0
            td = 0
            for k in range(4):
                t += dd[k] - ded(k)
                td += ded(k)
            d41 = t / 4.0
            d["mode"] = "avg_inv"
            d["ded"] = td / 4.0
        elif inv_ok and qi[0] is not None and qi[0] > 0:
            d41 = bal - ded(0)
            d["mode"] = "bal_inv"
            d["ded"] = ded(0)
        else:
            d41 = d43
            d["mode"] = "avg"
        st44 = st
        for x in ss:
            if x is not None and x > st44:
                st44 = x
    else:
        d43 = bal
        dd0 = ded(0)
        d41 = bal - dd0
        d["ded"] = dd0
        d["mode"] = "bal_inv" if dd0 > 0 else "bal"
        st44 = st
    d["d41"] = d41
    d["d43"] = d43
    d["st44"] = st44
    return d

def interest_data(ctx, D):
    i0 = gnum(ctx, "fin_int")
    if i0 is None:
        i0 = 0
    avg = (D["begin"] + D["bal"]) / 2.0
    eff = i0 / avg if avg > 0 else None
    mr, msrc, mnote = market_rate(ctx)
    kr = parse_num(ctx["raw"].get("key_rate"))
    thr = kr / 100.0 * ctx["settings"]["low_rate_share"] / 100.0 if kr is not None else None
    zero = D["begin"] <= 0 and D["bal"] <= 0 and i0 == 0
    recompute = False
    why = None
    cond = None
    if avg > 0 and i0 == 0:
        cond = "долг есть, а проценты равны нулю"
    elif avg > 0 and thr is not None and eff is not None and eff < thr:
        cond = "эффективная ставка ниже %s%% ключевой ставки" % fmt_num(ctx["settings"]["low_rate_share"], 0)
    if cond is not None:
        if mr * avg > i0:
            recompute = True
            why = cond
        else:
            # нормализация не должна уменьшать проценты: рыночная ставка не выше фактической
            _warn_once(ctx, "Эффективная ставка компании %s%% ниже порога нормализации (%s%% ключевой ставки), но рыночная ставка %s%% (%s) не выше её — проценты оставлены фактическими. Проверьте рыночную ставку." % (
                fmt_pct(eff * 100), fmt_num(ctx["settings"]["low_rate_share"], 0), fmt_pct(mr * 100), MARKET_SRC[msrc]))
    if avg > 0 and thr is None and cond is None:
        _warn_once(ctx, "Ключевая ставка НБКР не указана — проверка аномально низкой ставки (нормализация процентов) не выполнена.")
    if recompute and kr is not None and mr * 100 < kr:
        _warn_once(ctx, "Рыночная ставка для нормализации %s%% (%s) ниже ключевой ставки НБКР %s%%: банки обычно кредитуют выше ключевой ставки, вероятно, в ставку входят льготные программы. Проверьте ставку или задайте свою ставку подсектора." % (
            fmt_pct(mr * 100), MARKET_SRC[msrc], fmt_pct(kr)))
    used = mr * avg if recompute else i0
    return {"actual": i0, "avg_debt": avg, "eff": eff, "recompute": recompute, "why": why, "used": used, "zero": zero, "market": mr,
            "market_src": msrc, "market_note": mnote, "threshold": thr}

def _warn_once(ctx, msg):
    if msg not in ctx["warnings"]:
        ctx["warnings"].append(msg)

MARKET_SRC = {"input": "ставка аналитика для отрасли", "sub": "ставка подсектора из «Настроек»",
              "nbkr": "ставка из бюллетеня НБКР", "segments": "по долям сегментов агрохолдинга", "all": "общая ставка из «Настроек»"}

def fmt_pct(x):
    return fmt_num(x, 2).rstrip("0").rstrip(",")

def market_rate(ctx):
    """Рыночная ставка для нормализации процентов: введённая аналитиком для отрасли (с источником) или из настроек."""
    st = ctx["settings"]
    v = parse_num(ctx["raw"].get("mkt_rate"))
    src = raw_str(ctx["raw"].get("s_mkt_rate"))
    if v is not None:
        if not (0.1 <= v <= 100):
            _warn_once(ctx, "Рыночная ставка для отрасли %s%% вне допустимого диапазона 0,1–100%% — используется %s%% (%s)." % (fmt_pct(v), fmt_pct(st["market_rate"]), MARKET_SRC[st["market_src"]]))
        elif not src:
            _warn_once(ctx, "Рыночная ставка для отрасли указана без источника — не учитывается; используется %s%% (%s)." % (fmt_pct(st["market_rate"]), MARKET_SRC[st["market_src"]]))
        else:
            return v / 100.0, "input", src
    return st["market_rate"] / 100.0, st["market_src"], st.get("market_note")

def lev_scores(ctx, E, intr, tax, div, d41, d43, cash, zero, stress=False):
    b = ctx["settings"]["bounds"]
    out = {"ebitda": E, "interest": intr, "tax": tax, "div": div, "d41": d41, "d43": d43, "cash": cash,
           "v41": None, "v42": None, "v43": None, "s41": None, "s42": None, "s43": None, "ffo": None, "rcf": None, "nd": None,
           "n41": None, "n42": None, "n43": None}
    if E is None:
        out["s41"] = DEFAULT_SCORE
        out["s42"] = DEFAULT_SCORE
        out["s43"] = DEFAULT_SCORE
        out["missing"] = True
        return out
    out["missing"] = False
    if E <= 0:
        out["s41"] = 20.5
        out["n41"] = "EBITDA ≤ 0"
    else:
        out["v41"] = d41 / E
        out["s41"] = q(score_value(out["v41"], b["de"], "lower"), 2)
    if E <= 0:
        out["s42"] = 20.5
        out["n42"] = "EBITDA ≤ 0"
    elif zero or intr <= 0:
        out["s42"] = 0.5
        out["n42"] = "Долга и процентов нет"
    else:
        out["v42"] = E / intr
        out["s42"] = q(score_value(out["v42"], b["ic"], "higher"), 2)
    ffo = E - intr - tax
    rcf = ffo - div
    nd = d43 - cash
    out["ffo"] = ffo
    out["rcf"] = rcf
    out["nd"] = nd
    if nd <= 0:
        out["s43"] = 0.5 if rcf > 0 else 20.5
        out["n43"] = "Чистый долг ≤ 0, RCF %s" % ("> 0" if rcf > 0 else "≤ 0")
    else:
        out["v43"] = rcf / nd * 100
        out["s43"] = q(score_value(out["v43"], b["rcf"], "higher"), 2)
    return out

def liq_case(ctx, cash, undrawn, ffo, st44, capex, div, adv):
    num = cash + undrawn + (ffo if ffo is not None else 0)
    den = st44 + capex + div + adv
    if ffo is None:
        return {"num": None, "den": den, "value": None, "score": DEFAULT_SCORE, "missing": True, "note": None}
    if den <= 0:
        return {"num": num, "den": den, "value": None, "score": 0.5, "missing": False, "note": "Потребностей в ликвидности нет"}
    v = num / den
    return {"num": num, "den": den, "value": v, "score": q(score_value(v, ctx["settings"]["bounds"]["liq"], "higher"), 2), "missing": False, "note": None}

# ── Базовый сценарий (раздел В.6)

def forecast_base(ctx, series, m3):
    rev0 = gnum(ctx, "rev_0")
    fc = {"rev0": rev0, "bp": not gbool(ctx, "bp_none"), "notes": []}
    if rev0 is None:
        fc["B"] = None
        fc["E"] = None
        return fc
    g3 = ctx["g3"]
    base = rev0
    fc["base_III"] = None
    if g3 > 0:
        i0 = nz(parse_num(ctx["raw"].get("infl_0"))) / 100.0
        i1 = nz(parse_num(ctx["raw"].get("infl_1"))) / 100.0
        vals = []
        for y in range(3):
            r = gnum(ctx, "rev_%d" % y)
            if r is None:
                break
            f = 1.0
            if y >= 1:
                f = f * (1 + i0)
            if y >= 2:
                f = f * (1 + i1)
            vals.append(r * f)
        s = 0
        for v in vals:
            s += v
        b3 = s / len(vals)
        fc["base_III"] = b3
        fc["base_years"] = len(vals)
        base = g3 * b3 + (1 - g3) * rev0
    fc["base"] = base
    infl = parse_num(ctx["raw"].get("infl_fc"))
    fc["infl"] = infl
    g = 0
    newcap = 0
    gadd = 0
    if fc["bp"]:
        bg = parse_num(ctx["raw"].get("bp_growth"))
        cap = nz(infl) + 5
        g = min(nz(bg), cap)
        fc["g_bp"] = bg
        fc["g_cap"] = cap
        nr = gnum(ctx, "newcap_rev")
        nm = parse_num(ctx["raw"].get("newcap_month"))
        if nr is not None and nr > 0 and nm is not None and 1 <= nm <= 12:
            newcap = min(nr * (13 - int(nm)) / 12.0, 0.5 * nr)
        if ctx["garden"]:
            price = gnum(ctx, "garden_price")
            if price is not None and price > 0:
                add = 0
                for r in garden_rows(ctx):
                    if r["phase"] in ("young", "entering"):
                        nxt = garden_phase(r["kind"], r["age"] + 1)[1]
                        inc = nxt - r["coef"]
                        if inc > 0:
                            add += inc * r["area"] * GARDEN[r["kind"]]["yield"]
                gadd = 0.5 * add * price
    fc["g"] = g
    fc["newcap"] = newcap
    fc["garden_add"] = gadd
    B = base * (1 + g / 100.0) + newcap + gadd
    fc["B"] = B
    m = m3
    if fc["bp"]:
        bm = parse_num(ctx["raw"].get("bp_margin"))
        fc["m_bp"] = bm
        if bm is not None and m3 is not None:
            m = min(bm, m3)
    fc["m"] = m
    fc["E"] = B * m / 100.0 if m is not None else None
    return fc

def avg_distributions(ctx):
    s = 0
    n = 0
    for y in range(3):
        vals = [gnum(ctx, "div_%d" % y), gnum(ctx, "buyback_%d" % y), gnum(ctx, "ownloan_%d" % y), gnum(ctx, "np_%d" % y)]
        if vals[0] is None and vals[1] is None and vals[2] is None and vals[3] is None:
            continue
        n += 1
        s += nz(vals[0]) + nz(vals[1]) + nz(vals[2])
    return s / n if n > 0 else 0

# ── Стресс: параметры сценария С1 (Е.2.2)

def c1_params(ctx, c):
    p = dict(SUBSECTORS[c]["c1"])
    if c == "FSH" and sub_group(ctx, "FSH") == "II":
        p = dict(SUBSECTORS["FSH"]["c1_proc"])
    if c == "FLR" and gbool(ctx, "flr_regulated"):
        p["t"] = 0.5
    if c == "CRP":
        pp = ctx["crp_p"] / 100.0
        a = 1 - pp
        w = parse_num(ctx["raw"].get("crp_water_share"))
        if w is None or not text_ok(gstr(ctx, "crp_water_doc")):
            w = 0
        w = max(0, min(100, w)) / 100.0
        st = parse_num(ctx["raw"].get("stone_share"))
        p["stone_default"] = st is None and pp > 0
        st = 1.0 if st is None else max(0, min(100, st)) / 100.0
        do_a = 0.40 * (1 - w) + 0.25 * w
        do_g = 0.60 * st + 0.30 * (1 - st)
        p["d_o"] = a * do_a + pp * do_g
        p["vsh"] = a * 0.15 + pp * 0.20
        p["water"] = w
        p["stone"] = st
    return p

def v_for(ctx, c):
    v = parse_num(ctx["raw"].get("v_share"))
    if v is not None and v >= 0 and v <= 100:
        return v / 100.0
    return V_DEFAULT[sub_group(ctx, c)]

def c1_delta(B, C, v, p):
    vsh = v if p["vsh"] == "v" else p["vsh"]
    return B * p["d_o"] * (1 - vsh) + B * (1 - p["d_o"]) * p["d_c"] + C * (1 - p["d_o"]) * p["r"] * (1 - p["t"])

def stress_c1(ctx, B, k):
    parts = []
    tot = 0
    for c in ctx["segs"]:
        p = c1_params(ctx, c)
        if ctx["is_int"]:
            Bc = B * ctx["shares"][c] / 100.0
            rc = gnum(ctx, "seg_raw_" + c)
        else:
            Bc = B
            rc = gnum(ctx, "raw_cost")
        if rc is not None:
            Cc = rc * k
            cdef = False
        else:
            Cc = C_DEFAULT[sub_group(ctx, c)] * Bc
            cdef = True
        v = v_for(ctx, c)
        dlt = c1_delta(Bc, Cc, v, p)
        parts.append({"sub": c, "B": Bc, "C": Cc, "C_default": cdef, "v": v, "d_o": p["d_o"], "d_c": p["d_c"], "r": p["r"], "t": p["t"],
                      "vsh": v if p["vsh"] == "v" else p["vsh"], "delta": dlt, "shock": p["shock"]})
        tot += dlt
    return tot, parts

def company_t(ctx):
    if not ctx["is_int"]:
        return c1_params(ctx, ctx["main"])["t"] if ctx["main"] is not None else 0
    t = 0
    for c in ctx["segs"]:
        t += ctx["seg_w"][c] * c1_params(ctx, c)["t"]
    return t

def company_v(ctx):
    v = parse_num(ctx["raw"].get("v_share"))
    if v is not None and v >= 0 and v <= 100:
        return v / 100.0
    if not ctx["is_int"]:
        return V_DEFAULT[sub_group(ctx, ctx["main"])]
    t = 0
    for c in ctx["segs"]:
        t += ctx["seg_w"][c] * V_DEFAULT[sub_group(ctx, c)]
    return t

# ── Корректировки (раздел Г)

def next_two_quarters_share(ctx):
    qs = [gnum(ctx, "q_rev_%d" % i) for i in range(1, 5)]
    bd = ctx["bal_date"]
    if None in qs or bd is None:
        return None
    t = qs[0] + qs[1] + qs[2] + qs[3]
    if t <= 0:
        return None
    qb = (bd[1] - 1) // 3
    a = (qb + 1) % 4
    b = (qb + 2) % 4
    return (qs[a] + qs[b]) / t

def adjustments(ctx, A, ev):
    items = []
    caps = []
    lt = gnum(ctx, "liab_total")
    ou = gnum(ctx, "oth_undisclosed")
    if lt is not None and lt > 0 and ou is not None:
        r = ou / lt * 100
        n = -2 if r > 20 else (-1 if r > 10 else 0)
        items.append({"id": "undisclosed", "notches": n, "value": r, "unit": "%"})
    fxd = A["fx_debt"]
    fxr = A["fx_rev"]
    if fxd > 0 or fxr > 0:
        ds = fxd / A["debt"] * 100 if A["debt"] > 0 else 0
        rs = fxr / A["rev"] * 100 if A["rev"] > 0 else 0
        gap = ds - rs
        n = -2 if gap > 60 else (-1 if gap > 30 else 0)
        items.append({"id": "fx", "notches": n, "value": gap, "unit": "п.п.", "debt_share": ds, "rev_share": rs})
    ss = parse_num(ctx["raw"].get("state_share"))
    rg = parse_num(ctx["raw"].get("regulated_share"))
    n = 0
    plus = (ss is not None and ss >= 50) or gbool(ctx, "f_strategic")
    minus = rg is not None and rg >= 30
    if plus:
        n += 1
    if minus:
        n -= 1
    if plus or minus:
        items.append({"id": "state", "notches": n, "value": None, "plus": plus, "minus": minus})
    ps = parse_num(ctx["raw"].get("permit_share"))
    if ps is not None and ps >= 30:
        items.append({"id": "event", "notches": -2 if gbool(ctx, "f_permit_active") else -1, "value": ps, "unit": "%"})
    pl = gnum(ctx, "pledge_owners")
    nm = gnum(ctx, "nonmarket_deals")
    n = 0
    pv = None
    nv = None
    if pl is not None and pl > 0:
        eq = A["equity"]
        if eq is None or eq <= 0:
            n -= 2
        else:
            pv = pl / eq * 100
            if pv > 50:
                n -= 2
            elif pv > 25:
                n -= 1
    if nm is not None and nm > 0:
        ae = gnum(ctx, "assets_end")
        if ae is not None and ae > 0:
            nv = nm / ae * 100
            if nv > 10:
                n -= 3
    if n < -3:
        n = -3
    if (pl is not None and pl > 0) or (nm is not None and nm > 0):
        items.append({"id": "pledges", "notches": n, "value": pv, "unit": "%", "nonmarket": nv})
    # кризисная ликвидность
    r6 = nz(gnum(ctx, "repay6"))
    d6 = nz(gnum(ctx, "div6"))
    capex = nz(gnum(ctx, "capex12"))
    den = r6 + 0.5 * capex + d6
    share = 0.5
    how = "half"
    if ctx["seasonal"]:
        sh = next_two_quarters_share(ctx)
        if sh is not None:
            share = sh
            how = "seasonal"
    if den > 0 and A["ffo"] is not None:
        ffo6 = A["ffo"] * share
        ratio = (A["cash"] + A["undrawn"] + ffo6) / den
        n = -3 if ratio < 0.5 else (-2 if ratio < 0.7 else (-1 if ratio < 1.0 else 0))
        items.append({"id": "crisis", "notches": n, "value": ratio, "unit": "x", "ffo6": ffo6, "share6": share, "how": how})
    # ПОД/ФТ
    if gbool(ctx, "f53_sanct"):
        items.append({"id": "aml", "notches": 0, "value": None, "cap": True, "what": "sanctions"})
        caps.append("Санкции США, ЕС или Великобритании — итоговая оценка не выше B1")
    elif gbool(ctx, "f53_crim"):
        items.append({"id": "aml", "notches": -1, "value": None, "what": "criminal"})
    # кредитная история
    if ev["default"]:
        items.append({"id": "credit", "notches": -2, "value": None, "cap": True, "what": "default"})
        caps.append("Дефолт за 5 лет — итоговая оценка не лучше B1")
    else:
        n = 0
        if ev["type3"]:
            n -= 1
        if ev["refused"]:
            n -= 1
        if n != 0:
            items.append({"id": "credit", "notches": n, "value": None, "what": ("type3" if ev["type3"] else "") + ("+refused" if ev["refused"] else "")})
    tot = 0
    for it in items:
        tot += it["notches"]
    return {"items": items, "notches": tot, "cap_b1": len(caps) > 0, "caps": caps}

def apply_rating(agg, adj):
    base = rating_index(agg)
    idx = base - adj["notches"]
    if idx < 0:
        idx = 0
    if idx > len(RATING_SCALE) - 1:
        idx = len(RATING_SCALE) - 1
    capped = False
    if adj["cap_b1"] and idx < CAP_B1_INDEX:
        idx = CAP_B1_INDEX
        capped = True
    return base, idx, capped

def aggregate(ctx, scores):
    w = ctx["settings"]["weights"]
    tot = 0
    s = 0
    for code in SF_CODES:
        tot += w[code]
        s += w[code] * scores[code]
    return q(s / tot, 2) if tot > 0 else DEFAULT_SCORE

# ── Блок 4: факт, прогноз, стресс

def block4(ctx, series, m3, ev):
    D = debt_data(ctx)
    I = interest_data(ctx, D)
    tax, tsrc = tax_fact(ctx)
    e0 = year_ebitda(ctx, 0)
    E0 = e0["ebitda"] if e0 is not None else None
    div0 = nz(gnum(ctx, "div_0"))
    fact = lev_scores(ctx, E0, I["used"], tax, div0, D["d41"], D["d43"], D["cash"], I["zero"])
    # справочно: покрытие по фактическим процентам, если проценты нормализованы
    I["ic_actual"] = E0 / I["actual"] if I["recompute"] and I["actual"] > 0 and E0 is not None and E0 > 0 else None
    fact_nod = None
    if D["ded"] > 0 and E0 is not None and E0 > 0:
        fact_nod = D["d43"] / E0
    fc = forecast_base(ctx, series, m3)
    newl = nz(gnum(ctx, "new_loans"))
    rep = nz(gnum(ctx, "repay12"))
    delta = newl - rep
    end_f = max(0, D["bal"] + delta)
    d41f = max(0, D["d41"] + delta)
    d43f = max(0, D["d43"] + delta)
    avg_f = (D["bal"] + end_f) / 2.0
    if I["recompute"]:
        rate_f = max(I["eff"] if I["eff"] is not None else 0, I["market"])
    elif I["eff"] is not None:
        rate_f = I["eff"]
    else:
        rate_f = I["market"] if avg_f > 0 else 0
    int_f = avg_f * rate_f
    divp = nz(gnum(ctx, "div_policy"))
    divavg = avg_distributions(ctx)
    div_f = max(divp, divavg)
    trate = tax_rate_forecast(ctx, tax)
    da0 = nz(gnum(ctx, "da_0"))
    E = fc["E"]
    tax_f = 0
    if E is not None:
        pbt_f = E - da0 - int_f
        tax_f = trate * pbt_f if pbt_f > 0 else 0
    zero_f = avg_f <= 0 and int_f == 0
    fcs = lev_scores(ctx, E, int_f, tax_f, div_f, d41f, d43f, D["cash"], zero_f)
    capex12 = nz(gnum(ctx, "capex12"))
    liq = liq_case(ctx, D["cash"], D["undrawn"], fcs["ffo"], D["st44"], capex12, div_f, D["adv"])
    fc.update({"new_loans": newl, "repay12": rep, "debt_end": end_f, "d41": d41f, "d43": d43f, "avg_debt": avg_f, "rate": rate_f,
               "interest": int_f, "div": div_f, "div_policy": divp, "div_avg": divavg, "tax_rate": trate, "tax": tax_f, "capex12": capex12,
               "scores": fcs, "liq": liq})
    out = {"debt": D, "int": I, "tax": tax, "tax_src": tsrc, "E0": E0, "div0": div0, "fact": fact, "fact_nod": fact_nod, "fc": fc}
    # стресс-сценарии
    k = (fc["B"] / fc["rev0"]) if (fc["B"] is not None and fc["rev0"] is not None and fc["rev0"] > 0) else 1
    fxd = nz(gnum(ctx, "fx_debt"))
    fxrate = nz(parse_num(ctx["raw"].get("fx_rate"))) / 100.0
    fxr = nz(gnum(ctx, "fx_rev"))
    imp = nz(gnum(ctx, "imp_cost"))
    ext = nz(gnum(ctx, "export_top"))
    flt = nz(gnum(ctx, "float_debt"))
    scen = []
    if E is not None:
        B = fc["B"]
        for sid in ["C1", "C2", "C3", "C4"]:
            dE = 0
            d_int = 0
            d_debt = 0
            det = {}
            if sid == "C1":
                dE, parts = stress_c1(ctx, B, k)
                det["parts"] = parts
            elif sid == "C2":
                t = company_t(ctx)
                gain = 0.25 * fxr * k
                loss = 0.25 * imp * k * (1 - t)
                dE = loss - gain
                d_debt = 0.25 * fxd
                d_int = 0.25 * fxd * fxrate
                det = {"fx_rev_gain": gain, "import_loss": loss, "t": t, "fx_debt_add": d_debt, "fx_int_add": d_int}
            elif sid == "C3":
                v = company_v(ctx)
                lost = 0.5 * ext * k
                dE = lost * (1 - v)
                det = {"lost_rev": lost, "v": v}
            else:
                d_int = 0.05 * flt
                det = {"float_debt": flt, "int_add": d_int}
            Es = E - dE
            ints = int_f + d_int
            pbt_s = Es - da0 - ints
            tax_s = trate * pbt_s if pbt_s > 0 else 0
            d41s = d41f + D["oth_st"] + d_debt
            d43s = d43f + D["oth_st"] + d_debt
            zs = (avg_f + d_debt) <= 0 and ints == 0
            ls = lev_scores(ctx, Es, ints, tax_s, div_f, d41s, d43s, D["cash"], zs, stress=True)
            lq = liq_case(ctx, D["cash"], D["undrawn"], ls["ffo"], D["st44"] + D["oth_st"], capex12, div_f, D["adv"])
            scen.append({"id": sid, "dE": dE, "E": Es, "interest": ints, "tax": tax_s, "d41": d41s, "d43": d43s, "scores": ls, "liq": lq,
                         "d_debt": d_debt, "detail": det})
    out["stress"] = scen
    out["k"] = k
    out["fx"] = {"debt": fxd, "rate": fxrate, "rev": fxr, "imp": imp, "export_top": ext, "float": flt}
    return out

def b4_subfactors(ctx, B4):
    fa = B4["fact"]
    fs = B4["fc"]["scores"]
    res = {}
    for code, key, metric in (("4.1", "41", "de"), ("4.2", "42", "ic"), ("4.3", "43", "rcf")):
        sf_ = fa["s" + key]
        sc_ = fs["s" + key]
        comb = q(0.5 * sf_ + 0.5 * sc_, 2)
        res[code] = {"code": code, "metric": metric, "fact": {"value": fa["v" + key], "score": sf_, "note": fa["n" + key]},
                     "fc": {"value": fs["v" + key], "score": sc_, "note": fs["n" + key]}, "raw": comb, "score": comb,
                     "cat": category_for_score(comb), "caps": [], "all_default": fa["missing"] and fs["missing"],
                     "unit": METRICS[metric]["unit"]}
    lq = B4["fc"]["liq"]
    res["4.4"] = {"code": "4.4", "metric": "liq", "value": lq["value"], "raw": lq["score"], "score": lq["score"],
                  "cat": category_for_value(lq["value"], ctx["settings"]["bounds"]["liq"], "higher") if lq["value"] is not None else category_for_score(lq["score"]),
                  "caps": [], "all_default": lq["missing"], "unit": "x", "note": lq["note"], "num": lq["num"], "den": lq["den"]}
    return res

# ════════════════════════════════════════════════════════════════════════════
# 11. ПОЛНЫЙ РАСЧЁТ
# ════════════════════════════════════════════════════════════════════════════

def inputs_for_hash(raw):
    out = {}
    if not isinstance(raw, dict):
        return out
    for f in FIELDS:
        v = raw.get(f["key"])
        if f["type"] == "bool":
            if raw_bool(v):
                out[f["key"]] = True
        else:
            s = raw_str(v)
            if s != "":
                out[f["key"]] = s
    for t in TABLE_ORDER:
        rows = raw.get(t)
        if isinstance(rows, list):
            rr = []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                d = {}
                for c in TABLES[t]["cols"]:
                    v = row.get(c["key"])
                    if c["type"] == "bool":
                        if raw_bool(v):
                            d[c["key"]] = True
                    else:
                        s = raw_str(v)
                        if s != "":
                            d[c["key"]] = s
                if len(d) > 0:
                    rr.append(d)
            if len(rr) > 0:
                out[t] = rr
    return out

def input_hash(raw):
    return sha256_hex(canonical(inputs_for_hash(raw)))

def scores_with(base, repl):
    out = {}
    for c in SF_CODES:
        out[c] = repl[c] if c in repl else base[c]
    return out

def compute(raw, settings=None, haircut=None):
    st, snotes = normalize_settings(settings) if settings is not None else (default_settings(), [])
    ctx = build_ctx(raw, st, haircut)
    res = {"model": MODEL_VERSION, "marking": MARKING, "status": None, "message": None, "errors": ctx["errors"], "warnings": ctx["warnings"] + snotes,
           "main": ctx["main"], "is_int": ctx["is_int"], "segs": ctx["segs"], "seg_w": ctx["seg_w"], "shares": ctx["shares"],
           "group": ctx["group"], "gshare": ctx["gshare"], "g3": ctx["g3"], "seasonal": ctx["seasonal"], "garden": ctx["garden"],
           "annual": ctx["annual"], "crp_p": ctx["crp_p"], "fx": ctx["fx"], "currency": ctx["currency"], "rate_avg": ctx["rate_avg"],
           "rate_end": ctx["rate_end"], "annualized": ctx["annualized"], "ann": ctx["ann"], "settings_changed": ctx["settings"]["changed"],
           "sub_source": ctx["sub_source"], "sub_selected": ctx["sub_selected"], "input_hash": input_hash(raw)}
    if len(ctx["errors"]) > 0:
        res["status"] = "error"
        res["message"] = "Расчёт невозможен: " + " ".join(ctx["errors"])
        res["result_hash"] = sha256_hex(canonical({"status": "error", "errors": ctx["errors"]}))
        return res
    series = margin_series(ctx)
    res["series"] = series
    sf = {}
    sf["1.1"] = sf_11(ctx)
    sf["1.2"] = sf_12(ctx)
    sf["1.3"] = sf_13(ctx)
    sf["1.4"] = sf_14(ctx)
    sf["1.5"] = sf_15(ctx, series)
    sf["1.6"] = sf_16(ctx)
    sf["2.1"] = sf_21(ctx)
    sf["2.2"] = sf_22(ctx)
    sf["2.3"] = sf_23(ctx)
    sf["3.1"] = sf_31(ctx, series)
    sf["3.2"] = sf_32(ctx, series)
    m3 = sf["3.1"]["value"]
    restr = restructurings(ctx)
    ev = credit_events(ctx, restr)
    B4 = block4(ctx, series, m3, ev)
    b4 = b4_subfactors(ctx, B4)
    for c in ["4.1", "4.2", "4.3", "4.4"]:
        sf[c] = b4[c]
    tests = integrity_tests(ctx)
    sf["5.1"] = sf_51(ctx)
    sf["5.2"] = sf_52(ctx, tests)
    sf["5.3"] = sf_53(ctx)
    sf["6.1"] = sf_61(ctx, ev)
    sf["6.2"] = sf_62(ctx)
    sf["6.3"] = sf_63(ctx, ev)
    for c in SF_CODES:
        sf[c]["code"] = c
        sf[c]["weight"] = ctx["settings"]["weights"][c]
        if "cat" not in sf[c] or sf[c]["cat"] is None:
            sf[c]["cat_score"] = category_for_score(sf[c]["score"])
        else:
            sf[c]["cat_score"] = category_for_score(sf[c]["score"])
    res["sf"] = sf
    res["restr"] = restr
    res["credit"] = ev
    res["b4"] = B4
    for w_ in ctx["warnings"]:
        if w_ not in res["warnings"]:
            res["warnings"].append(w_)
    res["tests"] = tests
    scores = {}
    for c in SF_CODES:
        scores[c] = sf[c]["score"]
    res["scores"] = scores
    eq, _cut = equity_adjusted(ctx)
    rev0 = gnum(ctx, "rev_0")
    A = {"fx_debt": B4["fx"]["debt"], "fx_rev": B4["fx"]["rev"], "debt": B4["debt"]["bal"], "rev": nz(rev0), "equity": eq,
         "ffo": B4["fc"]["scores"]["ffo"], "cash": B4["debt"]["cash"], "undrawn": B4["debt"]["undrawn"]}
    adj = adjustments(ctx, A, ev)
    agg = aggregate(ctx, scores)
    base_idx, idx, capped = apply_rating(agg, adj)
    res["agg"] = agg
    res["adj"] = adj
    res["base_index"] = base_idx
    res["index"] = idx
    res["capped"] = capped
    res["rating_base"] = rating_info(base_idx, agg)
    res["rating"] = rating_info(idx, agg if idx == base_idx else None)
    # прогнозная оценка: 4.1–4.3 полностью по базовому сценарию
    fcs = B4["fc"]["scores"]
    sc_fc = scores_with(scores, {"4.1": fcs["s41"], "4.2": fcs["s42"], "4.3": fcs["s43"]})
    agg_fc = aggregate(ctx, sc_fc)
    _b, idx_fc, _c = apply_rating(agg_fc, adj)
    res["forecast"] = {"agg": agg_fc, "index": idx_fc, "rating": rating_info(idx_fc)}
    # стрессовая оценка: худшая из четырёх
    worst = None
    srs = []
    for s in B4["stress"]:
        ls = s["scores"]
        sc_s = scores_with(scores, {"4.1": ls["s41"], "4.2": ls["s42"], "4.3": ls["s43"], "4.4": s["liq"]["score"]})
        A2 = dict(A)
        A2["ffo"] = ls["ffo"]
        if s["id"] == "C2":
            A2["fx_debt"] = A["fx_debt"] * 1.25
            A2["debt"] = A["debt"] + 0.25 * A["fx_debt"]
            A2["fx_rev"] = A["fx_rev"] * 1.25
            A2["rev"] = A["rev"] + 0.25 * A["fx_rev"]
        adj_s = adjustments(ctx, A2, ev)
        agg_s = aggregate(ctx, sc_s)
        _b, idx_s, _c = apply_rating(agg_s, adj_s)
        item = {"id": s["id"], "agg": agg_s, "index": idx_s, "rating": rating_info(idx_s), "notches": adj_s["notches"],
                "s41": ls["s41"], "s42": ls["s42"], "s43": ls["s43"], "s44": s["liq"]["score"]}
        srs.append(item)
        if worst is None or idx_s > worst["index"]:
            worst = item
    res["stress"] = {"items": srs, "worst": worst}
    # прогноз по оценке (Е.2)
    res["outlook"] = outlook(ctx, idx, idx_fc, worst["index"] if worst else idx)
    # достаточность информации (В.5) и стоп-факторы
    suff = []
    if gnum(ctx, "rev_0") is None or gnum(ctx, "op_0") is None:
        suff.append(SUFFICIENCY_RULES[0])
    elif ctx["fy_type"] == "interim" and not gbool(ctx, "interim_typical"):
        suff.append(SUFFICIENCY_RULES[0] + " (промежуточный период не подтверждён как типичный — пересчёт в годовые данные не допускается)")
    dw = 0
    tw = 0
    dlist = []
    for c in SF_CODES:
        tw += ctx["settings"]["weights"][c]
        if sf[c]["all_default"]:
            dw += ctx["settings"]["weights"][c]
            dlist.append(c)
    res["default_weight"] = dw / tw * 100 if tw > 0 else 0
    res["default_list"] = dlist
    if tw > 0 and dw / tw * 100 > 20:
        suff.append(SUFFICIENCY_RULES[1] + " (сейчас %s%%: %s)" % (fmt_num(dw / tw * 100, 1), ", ".join(dlist)))
    if tests[0]["result"] == "fail" and tests[1]["result"] == "fail":
        suff.append(SUFFICIENCY_RULES[2])
    stops = stop_factors(ctx)
    res["stops"] = stops
    res["insufficient"] = suff
    if len(stops) > 0:
        res["status"] = "stop"
        res["message"] = "Оценка не присваивается: стоп-фактор ПОД/ФТ"
    elif len(suff) > 0:
        res["status"] = "insufficient"
        res["message"] = "Оценка не присваивается: недостаточно информации"
    else:
        res["status"] = "rated"
        res["message"] = None
    # справочный сценарий −30% при аннуализации
    res["ref30"] = None
    if ctx["annualized"] and haircut is None and res["status"] == "rated":
        r2 = compute(raw, settings, 0.7)
        if r2.get("status") in ("rated", "insufficient", "stop"):
            res["ref30"] = {"agg": r2["agg"], "index": r2["index"], "rating": r2["rating"]}
    core = {"status": res["status"], "agg": agg, "index": idx, "base": base_idx, "scores": scores,
            "fc": [agg_fc, idx_fc], "stress": [[x["id"], x["agg"], x["index"]] for x in srs], "outlook": res["outlook"]["code"],
            "adj": [[x["id"], x["notches"]] for x in adj["items"]], "ref30": res["ref30"]["index"] if res["ref30"] else None}
    res["core"] = core
    res["result_hash"] = sha256_hex(canonical(core))
    return res

def outlook(ctx, cur, fc, stv):
    better = cur - fc       # на сколько ступеней прогнозная выше текущей
    worse = stv - cur       # на сколько ступеней стрессовая ниже текущей
    reasons = []
    if gbool(ctx, "f_review"):
        code = "REVIEW"
        reasons.append("произошло событие, данных для пересчёта ещё нет")
    elif (better >= 1 and worse >= 3) or gbool(ctx, "f_event"):
        code = "DEVELOPING"
        if gbool(ctx, "f_event"):
            reasons.append("предстоит событие с неопределённым исходом (10% выручки или капитала и более)")
        if better >= 1 and worse >= 3:
            reasons.append("прогнозная оценка выше текущей на %d ступ., стрессовая ниже на %d ступ." % (better, worse))
    elif better <= -1 or worse >= 3:
        code = "NEGATIVE"
        if better <= -1:
            reasons.append("прогнозная оценка ниже текущей на %d ступ." % (-better))
        if worse >= 3:
            reasons.append("стрессовая оценка ниже текущей на %d ступ." % worse)
    elif better >= 1 and worse <= 1:
        code = "POSITIVE"
        reasons.append("прогнозная оценка выше текущей на %d ступ., стрессовая ниже не более чем на 1 ступ." % better)
    else:
        code = "STABLE"
        reasons.append("условия других прогнозов не выполнены")
    return {"code": code, "label": OUTLOOKS[code]["label"], "reasons": reasons, "better": better, "worse": worse}

