def _demo_common(company, analyst="Абдыкадырова А. Т."):
    return {"company": company, "analyst": analyst, "eval_date": "16.11.2026", "report_year": 2025, "bal_date": "31.12.2025",
            "fy_type": "year", "currency": "KGS", "key_rate": 12}

def _years(d, key, vals):
    for i in range(len(vals)):
        if vals[i] is not None:
            d["%s_%d" % (key, i)] = vals[i]

def _src(d, keys, text):
    for k in keys:
        d[k] = text

