# 14. ОТЧЁТ ДЛЯ КОМИТЕТА (Markdown)
# ════════════════════════════════════════════════════════════════════════════

def _n(x, d=2):
    return fmt_num(x, d) if is_num(x) else "—"

def _money(x):
    if not is_num(x):
        return "—"
    return fmt_num(x / 1e6, 1) + " млн сом"

def _ind_value(i):
    if i["value"] is None:
        return "—"
    u = i["unit"]
    v = fmt_num(i["value"], i["dec"])
    if u == "%":
        return v + "%"
    if u == "x":
        return v + "x"
    return (v + " " + u).strip()

def _sf_value(ctx_res, code):
    s = ctx_res["sf"][code]
    if code in ("4.1", "4.2", "4.3"):
        f = s["fact"]["value"]
        g = s["fc"]["value"]
        u = METRICS[s["metric"]]["unit"]
        return "факт %s; прогноз %s" % (_n(f, 2 if u == "x" else 1) + (u if f is not None else ""), _n(g, 2 if u == "x" else 1) + (u if g is not None else ""))
    v = s.get("value")
    if v is None:
        return "—"
    m = METRICS.get(s.get("metric"), {})
    u = s.get("unit") or m.get("unit", "")
    d = m.get("dec", 2)
    return (fmt_num(v, d) + ("%" if u == "%" else ("x" if u == "x" else (" " + u if u else "")))).strip()

def committee_report_md(res, raw=None):
    raw = raw or {}
    L = []
    comp = raw_str(raw.get("company")) or "Компания без названия"
    L.append("# Отчёт об оценке кредитоспособности: %s" % comp)
    L.append("")
    L.append("**%s.**" % MARKING)
    L.append("")
    L.append("Дата оценки: %s · Аналитик: %s · Последний полный финансовый год: %s · Дата баланса: %s" % (
        raw_str(raw.get("eval_date")) or "—", raw_str(raw.get("analyst")) or "—", raw_str(raw.get("report_year")) or "—",
        raw_str(raw.get("bal_date")) or "—"))
    L.append("")
    if res["status"] == "error":
        L.append("## Расчёт невозможен")
        for e in res["errors"]:
            L.append("- " + e)
        return "\n".join(L) + "\n"
    main = res["main"]
    L.append("## 1. Итог")
    if res["status"] == "rated":
        r = res["rating"]
        L.append("- **Итоговая оценка: %s (%s)**" % (r["national"], r["internal"]))
        L.append("- Прогноз по оценке: **%s** — %s" % (res["outlook"]["label"], "; ".join(res["outlook"]["reasons"])))
    else:
        L.append("- **%s**" % res["message"])
        for x in res["stops"]:
            L.append("  - стоп-фактор: " + x)
        for x in res["insufficient"]:
            L.append("  - " + x)
    rb = res["rating_base"]
    L.append("- Агрегированный балл скоркарда: %s → %s (%s); запас до границы со ступенью ниже: %s балла" % (
        _n(res["agg"]), rb["national"], rb["internal"], _n(rb["headroom"])))
    L.append("- Корректировки: %s ступ.%s" % (fmt_num(res["adj"]["notches"], 0), ("; " + "; ".join(res["adj"]["caps"])) if res["adj"]["caps"] else ""))
    L.append("- Прогнозная оценка (4.1–4.3 по базовому сценарию): %s; стрессовая (худший сценарий %s): %s" % (
        res["forecast"]["rating"]["national"], res["stress"]["worst"]["id"] if res["stress"]["worst"] else "—",
        res["stress"]["worst"]["rating"]["national"] if res["stress"]["worst"] else "—"))
    if res.get("ref30"):
        L.append("- Справочно: данные аннуализированы; при выручке и EBITDA на 30%% ниже оценка была бы %s (на баллы не влияет)" % res["ref30"]["rating"]["national"])
    L.append("")
    L.append("## 2. Профиль")
    if res["is_int"]:
        segs = ", ".join("%s %s%%" % (SUBSECTORS[c]["name"], fmt_num(res["shares"][c], 1)) for c in res["segs"])
        L.append("- Подсектор: **Интегрированный агрохолдинг**; сегменты от 10%% выручки: %s" % segs)
    else:
        how = "выбран в профиле компании" if res.get("sub_source") == "selected" else "определён по долям выручки (правило А.2)"
        L.append("- Подсектор: **%s** (%s); группа маржи %s" % (SUBSECTORS[main]["name"], how, res["group"]))
    L.append("- Валюта отчётности: %s%s" % (res["currency"], (" (средний курс %s, на дату баланса %s сом)" % (_n(res["rate_avg"], 4), _n(res["rate_end"], 4))) if res["fx"] else ""))
    if res["annualized"]:
        L.append("- Промежуточная отчётность пересчитана в годовую (множитель %s)" % _n(res["ann"], 2))
    L.append("")
    L.append("## 3. Скоркард")
    L.append("| Код | Подфактор | Вес | Значение | Балл | Категория | Ограничения |")
    L.append("|---|---|---|---|---|---|---|")
    for s in SUBFACTORS:
        x = res["sf"][s["code"]]
        caps = "; ".join(c["text"] for c in x["caps"] if not c.get("inactive"))
        if x["all_default"]:
            caps = ("нет данных (балл по умолчанию)" + ("; " + caps if caps else ""))
        L.append("| %s | %s | %s%% | %s | %s | %s | %s |" % (s["code"], s["name"], fmt_num(x["weight"], 0), _sf_value(res, s["code"]),
                                                            _n(x["score"]), x["cat_score"], caps or "—"))
    L.append("| | **Итого** | 100%% | | **%s** | %s | |" % (_n(res["agg"]), rb["internal"]))
    L.append("")
    L.append("## 4. Индикаторы метрических подфакторов")
    for s in SUBFACTORS:
        x = res["sf"][s["code"]]
        groups = []
        if "indicators" in x:
            groups.append(("", x["indicators"]))
        for p in x.get("parts", []):
            if "indicators" in p:
                groups.append((p.get("label", ""), p["indicators"]))
        for sg in x.get("segments", []):
            if "indicators" in sg:
                groups.append((sg.get("label", ""), sg["indicators"]))
            for p in sg.get("parts", []):
                groups.append((sg.get("label", "") + ": " + p.get("label", ""), p["indicators"]))
        if not groups:
            continue
        L.append("### %s %s" % (s["code"], s["name"]))
        for lbl, inds in groups:
            if lbl:
                L.append("*%s*" % lbl)
            L.append("| Индикатор | Вес | Значение | Категория | Балл | Примечание |")
            L.append("|---|---|---|---|---|---|")
            for i in inds:
                if i["na"]:
                    L.append("| %s %s | %s%% | не применяется | — | — | %s |" % (i["code"], i["name"], i["w"], i["note"] or ""))
                    continue
                L.append("| %s %s | %s%% | %s | %s | %s | %s |" % (i["code"], i["name"], i["w"], _ind_value(i), i["cat"] or "нет данных",
                                                               _n(i["score"], 0), i["note"] or ("" if i["src"] else "нет источника")))
        L.append("")
    b4 = res["b4"]
    fc = b4["fc"]
    L.append("## 5. Долговая нагрузка: факт и базовый сценарий")
    L.append("- Финансовый долг на дату баланса: %s; в 4.1: %s; в 4.3: %s (режим «%s»)" % (_money(b4["debt"]["bal"]), _money(b4["debt"]["d41"]), _money(b4["debt"]["d43"]), b4["debt"]["mode"]))
    if b4.get("fact_nod") is not None:
        L.append("- Справочно: Debt/EBITDA без вычета запасов %s" % _n(b4["fact_nod"]))
    I = b4["int"]
    L.append("- EBITDA последнего года: %s; проценты в расчёте: %s%s; налог на прибыль: %s" % (
        _money(b4["E0"]), _money(I["used"]), (" — нормализованы по рыночной ставке %s%% (%s; причина: %s); фактические %s" % (
            fmt_pct(I["market"] * 100), MARKET_SRC[I["market_src"]], I["why"], _money(I["actual"]))) if I["recompute"] else "", _money(b4["tax"])))
    if I["recompute"] and I.get("ic_actual") is not None:
        L.append("- Справочно: EBITDA / фактические проценты %s" % _n(I["ic_actual"]))
    L.append("- Рыночная ставка для нормализации процентов и прогноза: %s%% — %s%s" % (
        fmt_pct(I["market"] * 100), MARKET_SRC[I["market_src"]], (" (источник: %s)" % I["market_note"]) if I["market_note"] else ""))
    L.append("- Базовый сценарий: выручка %s (рост %s%%), маржа %s%%, EBITDA %s, долг на конец %s, проценты %s, дивиденды %s, налог %s" % (
        _money(fc.get("B")), _n(fc.get("g"), 1), _n(fc.get("m"), 1), _money(fc.get("E")), _money(fc.get("debt_end")), _money(fc.get("interest")),
        _money(fc.get("div")), _money(fc.get("tax"))))
    L.append("")
    L.append("## 6. Стресс-сценарии")
    L.append("| Сценарий | ΔEBITDA | 4.1 | 4.2 | 4.3 | 4.4 | Балл | Оценка |")
    L.append("|---|---|---|---|---|---|---|---|")
    for i in range(len(res["stress"]["items"])):
        it = res["stress"]["items"][i]
        sc = b4["stress"][i]
        L.append("| %s %s | %s | %s | %s | %s | %s | %s | %s |" % (it["id"], STRESS_SCENARIOS[i]["name"], _money(sc["dE"]), _n(it["s41"]), _n(it["s42"]),
                                                                _n(it["s43"]), _n(it["s44"]), _n(it["agg"]), it["rating"]["national"]))
    L.append("")
    L.append("## 7. Корректировки")
    names = {a["id"]: a["name"] for a in ADJUSTMENT_RULES}
    if not res["adj"]["items"]:
        L.append("Корректировки не применяются.")
    for it in res["adj"]["items"]:
        val = ""
        if it.get("value") is not None:
            val = " (%s %s)" % (_n(it["value"], 2 if it.get("unit") == "x" else 1), it.get("unit", ""))
        L.append("- %s: %s ступ.%s" % (names[it["id"]], fmt_num(it["notches"], 0), val))
    L.append("")
    if res["restr"]:
        L.append("## 8. Реструктуризации за 5 лет")
        for it in res["restr"]:
            L.append("- №%d от %s: вид %d%s" % (it["n"], it["date"] or "—", it["type"], (" — " + "; ".join(it["reasons"])) if it["reasons"] else ""))
        L.append("")
    L.append("## 9. Тесты целостности отчётности")
    tl = {"pass": "пройден", "fail": "не пройден", "explain": "требует пояснений", "": "не проверен"}
    for t in res["tests"]:
        L.append("- Тест %d. %s: %s" % (t["id"], INTEGRITY_TESTS[t["id"] - 1]["name"], tl.get(t["result"], t["result"])))
    L.append("")
    src_rows = []
    docs = raw.get("docs") if isinstance(raw, dict) and isinstance(raw.get("docs"), dict) else {}
    for f in FIELDS:
        if f["type"] != "source":
            continue
        txt = raw_str(raw.get(f["key"])) if isinstance(raw, dict) else ""
        lst = [m for m in (docs.get(f["key"]) or []) if isinstance(m, dict)]
        if txt or lst:
            src_rows.append((f["group"].split(":")[0], txt or "—", "; ".join(str(m.get("name") or "") for m in lst) or "—"))
    gen = [m for m in (docs.get("_general") or []) if isinstance(m, dict)]
    if src_rows or gen:
        L.append("## 10. Источники и документы")
        if src_rows:
            L.append("| Раздел | Источник | Документы |")
            L.append("|---|---|---|")
            for g, t, d in src_rows:
                L.append("| %s | %s | %s |" % (g, t.replace("|", "/"), d.replace("|", "/")))
        if gen:
            L.append("Общие документы компании: " + "; ".join(str(m.get("name") or "") for m in gen) + ".")
        L.append("")
    if res["warnings"]:
        L.append("## Замечания")
        for w in res["warnings"]:
            L.append("- " + w)
        L.append("")
    L.append("Код расчёта: ввод %s · результат %s" % (res["input_hash"][:16], res["result_hash"][:16]))
    return "\n".join(L) + "\n"

# ════════════════════════════════════════════════════════════════════════════
# 15. ЖИЗНЕННЫЙ ЦИКЛ ОЦЕНКИ: ПРОВЕРКА, КОМИТЕТ, РЕЙТИНГОВЫЕ ДЕЙСТВИЯ, МОНИТОРИНГ
#     (правила совпадают с web/src/process.js 1:1; сверка — tools/process_parity.py)
# ════════════════════════════════════════════════════════════════════════════

COMMITTEE = COMMITTEE_CFG
DECISION_STATUS = {d["value"]: d["status"] for d in COMMITTEE["decisions"]}
DECISION_LABEL = {d["value"]: d["label"] for d in COMMITTEE["decisions"]}
ACTION_LABEL = {a["value"]: a["label"] for a in COMMITTEE["actions"]}
REVIEW_LABEL = {a["value"]: a["label"] for a in COMMITTEE["review_states"]}
WORK_STATUSES = ("draft", "check", "committee")
_PDATE_RE = re.compile(r"^([0-9]{1,2})\.([0-9]{1,2})\.([0-9]{4})$")
DOC_ID_RE = re.compile(r"^[0-9a-f]{64}$")


def _mdays(y, m):
    if m == 2:
        return 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28
    return 30 if m in (4, 6, 9, 11) else 31


def date_iso(s):
    """«ДД.ММ.ГГГГ» → «ГГГГ-ММ-ДД» (или None, если дата неверная)."""
    m = _PDATE_RE.match(raw_str(s))
    if not m:
        return None
    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if y < 1900 or mo < 1 or mo > 12 or d < 1 or d > _mdays(y, mo):
        return None
    return "%04d-%02d-%02d" % (y, mo, d)


def iso_ru(iso):
    return "%s.%s.%s" % (iso[8:10], iso[5:7], iso[0:4])


def _ymd(iso):
    return int(iso[0:4]), int(iso[5:7]), int(iso[8:10])


def add_months(iso, n):
    y, m, d = _ymd(iso)
    t = y * 12 + (m - 1) + n
    y2, m2 = t // 12, t % 12 + 1
    return "%04d-%02d-%02d" % (y2, m2, min(d, _mdays(y2, m2)))


def _ordinal(iso):
    import datetime
    y, m, d = _ymd(iso)
    return datetime.date(y, m, d).toordinal()


def add_days(iso, n):
    import datetime
    return datetime.date.fromordinal(_ordinal(iso) + n).isoformat()


def days_between(a, b):
    return _ordinal(b) - _ordinal(a)


def person_key(s):
    """ФИО для сравнения: без регистра, лишних пробелов, «ё» = «е»."""
    return " ".join(raw_str(s).lower().replace("ё", "е").split())


def _d(x):
    return x if isinstance(x, dict) else {}


def _int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def committee_check(entry, process):
    """Проверка протокола по правилам процедуры. Возвращает ошибки этапа проверки вторым аналитиком,
    ошибки заседания комитета, предупреждения и решение (если ошибок нет)."""
    p = _d(process)
    chk = _d(p.get("check"))
    com = _d(p.get("committee"))
    e_chk, e_com, warns = [], [], []
    preparer = person_key(entry.get("analyst"))
    eval_iso = date_iso(entry.get("eval_date"))
    # 1. Проверка вторым аналитиком (принцип «четырёх глаз»)
    by = person_key(chk.get("by"))
    if not preparer:
        e_chk.append("В данных оценки не указан аналитик, подготовивший оценку (поле «Аналитик» в профиле).")
    if not by:
        e_chk.append("Не указан проверяющий — второй аналитик.")
    elif by == preparer:
        e_chk.append("Проверяющий совпадает с аналитиком, подготовившим оценку: проверку проводит другой сотрудник.")
    chk_iso = date_iso(chk.get("date"))
    if not chk_iso:
        e_chk.append("Дата проверки: укажите в формате ДД.ММ.ГГГГ.")
    elif eval_iso and chk_iso < eval_iso:
        e_chk.append("Дата проверки раньше даты оценки.")
    res = raw_str(chk.get("result"))
    if res not in ("ok", "remarks"):
        e_chk.append("Укажите результат проверки.")
    elif res == "remarks" and len(raw_str(chk.get("comment"))) < COMMITTEE["min_reason"]:
        e_chk.append("Опишите замечания проверяющего (не короче %d знаков)." % COMMITTEE["min_reason"])
    check_ok = not e_chk and res == "ok"
    # 2. Заседание комитета
    if not check_ok:
        e_com.append("Комитет рассматривает оценку только после проверки вторым аналитиком без замечаний.")
    number = raw_str(com.get("number"))
    if not number:
        e_com.append("Не указан номер протокола.")
    com_iso = date_iso(com.get("date"))
    if not com_iso:
        e_com.append("Дата заседания: укажите в формате ДД.ММ.ГГГГ.")
    elif chk_iso and com_iso < chk_iso:
        e_com.append("Дата заседания раньше даты проверки вторым аналитиком.")
    members = com.get("members") if isinstance(com.get("members"), list) else []
    seen = set()
    chairs = []
    n_voting = 0
    n_conf = 0
    votes = {"for": 0, "against": 0, "abstain": 0}
    for i, m in enumerate(members):
        m = _d(m)
        nm = person_key(m.get("name"))
        disp = raw_str(m.get("name"))
        if not nm:
            e_com.append("Состав комитета, строка %d: не указано ФИО." % (i + 1))
            continue
        if nm in seen:
            e_com.append("%s указан(а) в составе дважды." % disp)
            continue
        seen.add(nm)
        conflict = m.get("conflict") is True
        if raw_str(m.get("role")) == "chair":
            chairs.append((disp, conflict, nm))
        if preparer and nm == preparer:
            e_com.append("%s подготовил(а) оценку: докладчик не голосует и не входит в состав комитета." % disp)
            continue
        if conflict:
            n_conf += 1
            continue
        n_voting += 1
        v = raw_str(m.get("vote"))
        if v not in votes:
            e_com.append("%s: не указан голос." % disp)
            continue
        votes[v] += 1
    if len(chairs) != 1:
        e_com.append("В составе должен быть ровно один председатель (сейчас: %d)." % len(chairs))
    elif chairs[0][1]:
        e_com.append("Председатель заявил конфликт интересов — заседание ведёт другой член комитета.")
    if n_voting < COMMITTEE["quorum"]:
        e_com.append("Нет кворума: голосуют %d, нужно не меньше %d (члены с конфликтом интересов не голосуют)." % (n_voting, COMMITTEE["quorum"]))
    dec = raw_str(com.get("decision"))
    rated = entry.get("calc_status") == "rated" and _int(entry.get("final_index"))
    model_index = entry.get("final_index") if rated else None
    model_outlook = raw_str(entry.get("outlook_code")) if rated else None
    ri = com.get("rating_index")
    oc = raw_str(com.get("outlook"))
    rationale = raw_str(com.get("rationale"))
    if dec not in DECISION_STATUS:
        e_com.append("Выберите решение комитета.")
    elif DECISION_STATUS[dec] == "approved":
        if not rated:
            e_com.append("Программа не присвоила оценку (%s): комитет может только вернуть оценку на доработку или отклонить." % (raw_str(entry.get("message")) or "нет результата"))
        elif dec == "approve_dev":
            ok_ri = _int(ri) and 0 <= ri < len(RATING_SCALE)
            if not ok_ri:
                e_com.append("Выберите оценку, которую утверждает комитет.")
            if oc not in OUTLOOKS:
                e_com.append("Выберите прогноз, который утверждает комитет.")
            if ok_ri and oc in OUTLOOKS and ri == model_index and oc == model_outlook:
                e_com.append("Оценка и прогноз совпадают с программой — выберите «%s»." % DECISION_LABEL["approve"])
            if len(rationale) < COMMITTEE["min_rationale"]:
                e_com.append("Обоснование отклонения от программы — не короче %d знаков." % COMMITTEE["min_rationale"])
    elif len(rationale) < COMMITTEE["min_reason"]:
        e_com.append("Укажите причину решения (не короче %d знаков)." % COMMITTEE["min_reason"])
    if dec in DECISION_STATUS and n_voting >= COMMITTEE["quorum"] and votes["for"] * 2 <= n_voting:
        e_com.append("Решение не принято: «за» %d из %d голосующих — нужно больше половины." % (votes["for"], n_voting))
    decision = None
    if not e_chk and not e_com:
        st = DECISION_STATUS[dec]
        decision = {
            "decision": dec, "decision_label": DECISION_LABEL[dec], "status": st, "protocol": number,
            "date": iso_ru(com_iso), "date_iso": com_iso, "check_by": raw_str(chk.get("by")), "check_date": iso_ru(chk_iso),
            "votes_for": votes["for"], "votes_against": votes["against"], "votes_abstain": votes["abstain"],
            "voting": n_voting, "conflicts": n_conf, "chair": chairs[0][0],
            "model_index": model_index, "model_national": entry.get("final_national") if rated else None, "model_outlook": model_outlook,
            "final_index": None, "final_national": None, "final_internal": None, "outlook_code": None, "outlook_label": None,
            "deviation": None, "rationale": rationale,
        }
        if st == "approved":
            fi = model_index if dec == "approve" else ri
            fo = model_outlook if dec == "approve" else oc
            decision.update({"final_index": fi, "final_national": RATING_SCALE[fi]["national"], "final_internal": RATING_SCALE[fi]["internal"],
                             "outlook_code": fo, "outlook_label": OUTLOOKS[fo]["label"], "deviation": fi - model_index})
            dv = fi - model_index
            if dv != 0:
                warns.append("Решение комитета отличается от оценки программы на %d ступ. (%s → %s)%s." % (
                    abs(dv), RATING_SCALE[model_index]["national"], RATING_SCALE[fi]["national"],
                    " — значительное отклонение" if abs(dv) > COMMITTEE["big_deviation"] else ""))
            elif fo != model_outlook:
                warns.append("Комитет изменил прогноз программы: %s → %s." % (OUTLOOKS[model_outlook]["label"], OUTLOOKS[fo]["label"]))
    return {"errors_check": e_chk, "errors_committee": e_com, "warnings": warns, "check_ok": check_ok,
            "votes": votes, "voting": n_voting, "conflicts": n_conf, "decision": decision}


def deviation_text(dv):
    """Отклонение решения комитета от программы: индекс больше — оценка ниже."""
    if not _int(dv):
        return ""
    if dv == 0:
        return "нет"
    return ("ниже на %d ступ." if dv > 0 else "выше на %d ступ.") % abs(dv)


def withdrawal_check(entry, process):
    p = _d(process)
    d = _d(p.get("decision"))
    w = _d(p.get("withdrawal"))
    errs = []
    if d.get("status") != "approved":
        errs.append("Отозвать можно только оценку, утверждённую комитетом.")
    w_iso = date_iso(w.get("date"))
    if not w_iso:
        errs.append("Дата отзыва: укажите в формате ДД.ММ.ГГГГ.")
    elif d.get("date_iso") and w_iso < d["date_iso"]:
        errs.append("Дата отзыва раньше даты решения комитета.")
    if len(raw_str(w.get("reason"))) < COMMITTEE["min_reason"]:
        errs.append("Укажите причину отзыва (не короче %d знаков)." % COMMITTEE["min_reason"])
    if not person_key(w.get("by")):
        errs.append("Укажите, кто оформил отзыв.")
    return errs


def process_verify(e):
    """Перепроверка зафиксированного решения по протоколу (при записи в архив на сервере).
    Возвращает (None, []) — решения нет; (True, []) — решение воспроизводится; (False, ошибки)."""
    p = e.get("process")
    if not isinstance(p, dict) or not isinstance(p.get("decision"), dict):
        return None, []
    r = committee_check(e, p)
    errs = r["errors_check"] + r["errors_committee"]
    if not errs and canonical(r["decision"]) != canonical(p["decision"]):
        errs.append("Сохранённое решение не совпадает с протоколом.")
    if isinstance(p.get("withdrawal"), dict):
        errs += withdrawal_check(e, p)
    return (not errs), errs


def expected_status(e):
    p = _d(e.get("process"))
    d = _d(p.get("decision"))
    if not d.get("status"):
        return None
    return "withdrawn" if isinstance(p.get("withdrawal"), dict) else d["status"]


def company_key(e):
    inn = "".join(raw_str(e.get("inn")).split())
    return ("inn:" + inn) if inn else ("name:" + person_key(e.get("company")))


def _approved_decision(e):
    d = _d(_d(e.get("process")).get("decision"))
    if d.get("status") == "approved" and date_iso(d.get("date")) and _int(d.get("final_index")):
        return d
    return None


def rating_events(entries):
    ev = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        d = _approved_decision(e)
        if not d:
            continue
        p = e["process"]
        eid = raw_str(e.get("id"))
        ev.append((date_iso(d["date"]), 0, raw_str(p.get("finalized_at")), eid, "decision", e))
        w = p.get("withdrawal")
        if isinstance(w, dict) and date_iso(w.get("date")):
            ev.append((date_iso(w["date"]), 1, raw_str(w.get("at")), eid, "withdraw", e))
    ev.sort(key=lambda x: x[:4])
    return ev


def _action(code, key, e, iso, prev, state, reason=None):
    return {"key": key, "company": raw_str(e.get("company")), "inn": raw_str(e.get("inn")), "entry_id": raw_str(e.get("id")),
            "date": iso_ru(iso), "date_iso": iso, "action": code, "action_label": ACTION_LABEL[code],
            "prev_national": prev["national"] if prev else None, "prev_outlook": prev["outlook_label"] if prev else None,
            "national": state["national"] if state else None, "outlook": state["outlook_label"] if state else None,
            "protocol": state["protocol"] if state else None, "deviation": state["deviation"] if state else None, "reason": reason}


def rating_actions(entries):
    """Рейтинговые действия по компаниям в хронологическом порядке и текущее состояние каждой компании."""
    cur = {}
    out = []
    for iso, _o, _at, eid, kind, e in rating_events(entries):
        key = company_key(e)
        prev = cur.get(key)
        d = e["process"]["decision"]
        if kind == "decision":
            fi, oc = d["final_index"], d.get("outlook_code")
            if prev is None:
                code = "assigned"
            elif fi < prev["index"]:
                code = "upgraded"
            elif fi > prev["index"]:
                code = "downgraded"
            elif oc != prev["outlook_code"]:
                code = "review" if oc == "REVIEW" else "outlook"
            else:
                code = "affirmed"
            state = {"entry_id": eid, "index": fi, "national": d.get("final_national"), "internal": d.get("final_internal"),
                     "outlook_code": oc, "outlook_label": d.get("outlook_label"), "date": iso_ru(iso), "date_iso": iso,
                     "protocol": raw_str(d.get("protocol")), "deviation": d.get("deviation"),
                     "company": raw_str(e.get("company")), "inn": raw_str(e.get("inn")), "report_year": raw_str(e.get("report_year"))}
            out.append(_action(code, key, e, iso, prev, state))
            cur[key] = state
        elif prev is not None and prev["entry_id"] == eid:
            out.append(_action("withdrawn", key, e, iso, prev, None, raw_str(e["process"]["withdrawal"].get("reason"))))
            cur[key] = None
    return out, cur


def review_due(state):
    if state["outlook_code"] == "REVIEW":
        return add_days(state["date_iso"], COMMITTEE["watch_review_days"])
    return add_months(state["date_iso"], COMMITTEE["review_months"])


def monitoring(entries, today_iso):
    """Действующие оценки и сроки пересмотра на дату today_iso («ГГГГ-ММ-ДД»)."""
    actions, cur = rating_actions(entries)
    in_work = {}
    for e in entries:
        if isinstance(e, dict) and e.get("status") in WORK_STATUSES:
            k = company_key(e)
            in_work[k] = in_work.get(k, 0) + 1
    active, withdrawn = [], []
    for key in sorted(cur):
        st = cur[key]
        if st is None:
            last = [a for a in actions if a["key"] == key][-1]
            withdrawn.append({"key": key, "company": last["company"], "inn": last["inn"], "date": last["date"], "date_iso": last["date_iso"],
                              "reason": last["reason"], "prev_national": last["prev_national"], "in_work": in_work.get(key, 0)})
            continue
        nxt = review_due(st)
        left = days_between(today_iso, nxt)
        state = "overdue" if left < 0 else ("soon" if left <= COMMITTEE["soon_days"] else "ok")
        row = dict(st)
        row.update({"key": key, "next_review_iso": nxt, "next_review": iso_ru(nxt), "days_left": left, "review_state": state,
                    "review_label": REVIEW_LABEL[state], "in_work": in_work.get(key, 0),
                    "review_basis": ("прогноз «На пересмотре»: не позднее %d дней" % COMMITTEE["watch_review_days"]) if st["outlook_code"] == "REVIEW"
                    else ("плановый пересмотр через %d месяцев" % COMMITTEE["review_months"])})
        active.append(row)
    active.sort(key=lambda x: (x["next_review_iso"], x["company"], x["key"]))
    withdrawn.sort(key=lambda x: (x["date_iso"], x["key"]), reverse=True)
    counts = {"active": len(active), "overdue": sum(1 for a in active if a["review_state"] == "overdue"),
              "soon": sum(1 for a in active if a["review_state"] == "soon"), "withdrawn": len(withdrawn)}
    return {"today": today_iso, "active": active, "withdrawn": withdrawn, "actions": actions, "counts": counts}


# ── Документы-основания (файлы хранятся отдельно от архива, имя файла = SHA-256 содержимого)

def docs_of(inputs):
    """Список (поле, описание файла) из inputs["docs"]. Документы не влияют на расчёт."""
    d = inputs.get("docs") if isinstance(inputs, dict) else None
    out = []
    if isinstance(d, dict):
        for k in sorted(d):
            lst = d[k]
            if not isinstance(lst, list):
                continue
            for m in lst:
                if isinstance(m, dict) and isinstance(m.get("id"), str) and DOC_ID_RE.match(m["id"]):
                    out.append((k, m))
    return out


def files_dir(archive_path=None):
    return os.path.join(os.path.dirname(os.path.abspath(archive_path or default_archive_path())), "kyrgyz_rating_files")


def file_store(data, folder):
    sha = hashlib.sha256(data).hexdigest()
    if not os.path.isdir(folder):
        os.makedirs(folder)
    path = os.path.join(folder, sha)
    if not os.path.exists(path):
        tmp = path + ".tmp"
        with open(tmp, "wb") as fh:
            fh.write(data)
        os.replace(tmp, path)
    return sha


def file_ok(folder, fid, deep=False):
    if not DOC_ID_RE.match(fid or ""):
        return False
    path = os.path.join(folder, fid)
    if not os.path.isfile(path):
        return False
    if deep:
        h = hashlib.sha256()
        with open(path, "rb") as fh:
            for chunk in iter(lambda: fh.read(1 << 20), b""):
                h.update(chunk)
        return h.hexdigest() == fid
    return True


def doc_field_label(key):
    if key == "_general":
        return "Общие документы компании"
    f = next((x for x in FIELDS if x["key"] == key), None)
    return f["group"] if f else key


# ════════════════════════════════════════════════════════════════════════════
# 15а. ОТЧЁТНЫЙ ПЕРИОД: ГОДЫ И ДАТЫ ОТ ПОСЛЕДНЕГО ПОЛНОГО ГОДА; ПЕРЕНОС НА СЛЕДУЮЩИЙ ГОД
#     (совпадает с web/src/period.js 1:1; сверка — tools/period_parity.py)
# ════════════════════════════════════════════════════════════════════════════

def valid_year(v):
    x = parse_num(v)
    if x is None or x < 1990 or x > 2100:
        return None
    return int(x)


def add_months_eom(iso, n):
    """Сдвиг на n месяцев; последний день месяца остаётся последним (30.06 → 31.12, 28.02.2027 → 29.02.2028)."""
    y, m, d = _ymd(iso)
    if d == _mdays(y, m):
        t = y * 12 + (m - 1) + n
        y2, m2 = t // 12, t % 12 + 1
        return "%04d-%02d-%02d" % (y2, m2, _mdays(y2, m2))
    return add_months(iso, n)


def _year_end(iso):
    return iso[5:] == "12-31"


def period_info(raw):
    """Все годы и даты, которые программа выводит из отчётного периода (для подписей полей, отчёта и переноса)."""
    r = raw if isinstance(raw, dict) else {}
    ry = valid_year(r.get("report_year"))
    fy = raw_str(r.get("fy_type")) or "year"
    if fy not in ("year", "ltm", "interim"):
        fy = "year"
    mo = parse_num(r.get("interim_months"))
    mo = int(mo) if mo in (3, 6, 9) else 6
    bal = date_iso(r.get("bal_date"))
    ev = date_iso(r.get("eval_date"))
    hy = valid_year(r.get("harvest_year"))
    out = {"report_year": ry, "fy_type": fy, "interim_months": mo, "bal": bal, "eval": ev,
           "harvest_year": hy if hy is not None else ry, "bal_assumed": False}
    # дата баланса для производных периодов: если не указана, у годовой отчётности — 31.12 последнего года
    be = bal
    if be is None and ry is not None and fy == "year":
        be = "%04d-12-31" % ry
        out["bal_assumed"] = True
    out["bal_eff"] = be
    out["years"] = [ry - i for i in range(5)] if ry is not None else None
    out["begin"] = None
    out["m12_from"] = None
    out["fc_from"] = out["fc_to"] = out["f6_to"] = None
    out["quarters"] = None
    if be is not None:
        out["begin"] = add_days(add_months_eom(be, -12), 1) if fy == "ltm" else be[0:4] + "-01-01"
        out["m12_from"] = add_days(add_months_eom(be, -12), 1)
        out["fc_from"] = add_days(be, 1)
        out["fc_to"] = add_months_eom(be, 12)
        out["f6_to"] = add_months_eom(be, 6)
        out["quarters"] = [add_months_eom(be, -3 * k) for k in (1, 2, 3)]
    out["e36_from"] = add_days(add_months(ev, -36), 1) if ev else None
    out["e60_from"] = add_days(add_months(ev, -60), 1) if ev else None
    # следующий отчётный год
    out["next_year"] = ry + 1 if ry is not None else None
    out["next_bal"] = add_months_eom(be, 12) if be is not None else None
    return out


def next_year_inputs(raw, today_iso):
    """Данные новой оценки за следующий отчётный год. Возвращает (данные, None) или (None, текст ошибки)."""
    r = raw if isinstance(raw, dict) else {}
    pi = period_info(r)
    if pi["report_year"] is None:
        return None, "Укажите последний полный финансовый год — от него считается следующий."
    cfg = NEXT_YEAR_CFG
    out = {}
    for f in FIELDS:
        k = f["key"]
        if f["card"] == "profile" and k not in cfg["reset_profile"] and k in r:
            out[k] = copy.deepcopy(r[k])
    out["report_year"] = pi["next_year"]
    if pi["next_bal"] is not None:
        out["bal_date"] = iso_ru(pi["next_bal"])
    out["eval_date"] = iso_ru(today_iso)
    for key, n in cfg["shift"]:
        for y in range(n - 1, 0, -1):
            v = r.get("%s_%d" % (key, y - 1))
            if v is not None and v != "":
                out["%s_%d" % (key, y)] = copy.deepcopy(v)
    for dst, src in cfg["pairs"]:
        v = r.get(src)
        if v is not None and v != "":
            out[dst] = copy.deepcopy(v)
    hy = valid_year(r.get("harvest_year"))
    if hy is not None:
        out["harvest_year"] = hy + 1
    for t in cfg["tables"]:
        rows = r.get(t)
        if isinstance(rows, list) and len(rows) > 0:
            out[t] = copy.deepcopy(rows)
    return out, None

# ════════════════════════════════════════════════════════════════════════════
# 15б. БЮЛЛЕТЕНЬ НБКР: СТАВКИ ПО НОВЫМ КРЕДИТАМ В СОМАХ ПО ОТРАСЛЯМ (табл. IV.2.19)
#     Файл бюллетеня (.xlsx; бывает с расширением .xls) читается без внешних библиотек.
#     Разбор таблицы и выбор ставки совпадают с web/src/engine.js (nbkrExtract, nbkrRate);
#     сверка — tools/e2e_nbkr.py
# ════════════════════════════════════════════════════════════════════════════

NBKR_TABLE_NEW = "IV.2.19"
NBKR_TABLE_PORT = "IV.2.22"


def xlsx_sheets(data, want):
    """Листы книги Excel 2007+ (zip с XML) как сетки: {имя листа: [[значение, …], …]}; только листы из want."""
    import io as _io
    import zipfile as _zf
    import xml.etree.ElementTree as ET
    if data[:4] == b"\xd0\xcf\x11\xe0":
        raise ValueError("Файл в старом формате Excel 97–2003. Откройте его в Excel и сохраните как «Книга Excel (.xlsx)».")
    if data[:2] != b"PK":
        raise ValueError("Это не файл Excel: ожидается бюллетень НБКР в формате .xlsx (или .xls, сохранённый как .xlsx).")
    z = _zf.ZipFile(_io.BytesIO(data))
    ns = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
    rid = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    target = {}
    for r in rels:
        t = r.get("Target")
        t = t[1:] if t.startswith("/") else "xl/" + t
        target[r.get("Id")] = t
    ss = []
    if "xl/sharedStrings.xml" in z.namelist():
        for si in ET.fromstring(z.read("xl/sharedStrings.xml")).findall("m:si", ns):
            ss.append("".join(t.text or "" for t in si.iter("{%s}t" % ns["m"])))
    out = {}
    for sh in wb.find("m:sheets", ns):
        name = (sh.get("name") or "").strip()
        if name not in want:
            continue
        root = ET.fromstring(z.read(target[sh.get(rid)]))
        rows = {}
        for c in root.iter("{%s}c" % ns["m"]):
            ref = c.get("r")
            col = 0
            i = 0
            while i < len(ref) and ref[i].isalpha():
                col = col * 26 + (ord(ref[i].upper()) - 64)
                i += 1
            row = int(ref[i:]) - 1
            t = c.get("t")
            v = c.find("m:v", ns)
            if t == "s":
                val = ss[int(v.text)] if v is not None else None
            elif t == "inlineStr":
                val = "".join(x.text or "" for x in c.iter("{%s}t" % ns["m"]))
            elif t in ("str", "e", "b"):
                val = (v.text if v is not None else None) if t == "str" else None
            else:
                val = float(v.text) if v is not None and v.text not in (None, "") else None
            if val is not None and val != "":
                rows.setdefault(row, {})[col - 1] = val
        n = max(rows) + 1 if rows else 0
        grid = []
        for r in range(n):
            cells = rows.get(r, {})
            w = max(cells) + 1 if cells else 0
            grid.append([cells.get(k) for k in range(w)])
        out[name] = grid
    return out


def _cell_str(v):
    if v is None:
        return ""
    if isinstance(v, float):
        return str(int(v)) if v == int(v) else repr(v)
    return str(v).strip()


def _nbkr_table(grid):
    """Разбор таблицы «объёмы и ставки по отраслям»: {"years": {"2025": {отрасль: [ставка, объём]}}, "months": {"2025-01": …}}."""
    first = None
    lab = None
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if isinstance(v, str) and v.strip() == "Всего":
                first, lab = r, c
                break
        if first is not None:
            break
    if first is None:
        return None
    names = dict((n, k) for k, n in NBKR_SECTORS)
    srow = {}
    for r in range(first, len(grid)):
        row = grid[r]
        s = _cell_str(row[lab]) if lab < len(row) else ""
        if s.lower().startswith("из них"):
            break
        if s in names and names[s] not in srow:
            srow[names[s]] = r
    if "total" not in srow:
        return None
    ncol = max(len(row) for row in grid[:first]) if first > 0 else 0
    ncol = max(ncol, max(len(grid[r]) for r in srow.values()))
    years, months = {}, {}
    cur_year = None
    cur_key = None
    for c in range(lab + 1, ncol):
        texts = [grid[r][c] for r in range(first) if c < len(grid[r]) and grid[r][c] is not None]
        low = " ".join(_cell_str(t).lower() for t in texts)
        is_v = "объем" in low or "объём" in low
        is_r = "ставк" in low
        if not is_v and not is_r:
            continue
        if is_v:
            mon = None
            for t in texts:
                s = _cell_str(t).rstrip("*").strip()
                if len(s) == 4 and s.isdigit() and 1990 <= int(s) <= 2100:
                    cur_year = int(s)
                elif 1 <= len(s) <= 2 and s.isdigit() and 1 <= int(s) <= 12:
                    mon = int(s)
            if cur_year is None:
                cur_key = None
                continue
            cur_key = ("m", "%04d-%02d" % (cur_year, mon)) if mon is not None else ("y", "%04d" % cur_year)
        if cur_key is None:
            continue
        dst = months if cur_key[0] == "m" else years
        for k, r in srow.items():
            v = grid[r][c] if c < len(grid[r]) else None
            if not isinstance(v, float) or v != v:
                continue
            e = dst.setdefault(cur_key[1], {}).setdefault(k, [None, None])
            e[1 if is_v else 0] = v
    def clean(d):
        out = {}
        for p in sorted(d):
            row = {}
            for k, (rt, vol) in d[p].items():
                if rt is not None and vol is not None and 0 < rt < 100 and vol > 0:
                    row[k] = [rt, vol]
            if row:
                out[p] = row
        return out
    return {"years": clean(years), "months": clean(months)}


def nbkr_extract(sheets, fname=""):
    """Ставки из бюллетеня: новые кредиты в сомах (IV.2.19) и справочно портфель в сомах (IV.2.22)."""
    tit = ""
    for row in sheets.get("Титул", []):
        for v in row:
            s = _cell_str(v)
            m = re.search(r"№\s*(\d{1,2}\s*/\s*\d{4})", s)
            if m:
                tit = "№" + m.group(1).replace(" ", "")
                break
        if tit:
            break
    if NBKR_TABLE_NEW not in sheets:
        raise ValueError("В файле нет таблицы %s «Объёмы и процентные ставки по вновь выданным кредитам в национальной валюте». Нужен бюллетень НБКР целиком." % NBKR_TABLE_NEW)
    new = _nbkr_table(sheets[NBKR_TABLE_NEW])
    if new is None or (not new["years"] and not new["months"]):
        raise ValueError("Таблица %s не распознана: не найдены строки отраслей или столбцы «общий объем» / «средневз. ставка». Возможно, НБКР изменил формат." % NBKR_TABLE_NEW)
    port = _nbkr_table(sheets[NBKR_TABLE_PORT]) if NBKR_TABLE_PORT in sheets else None
    return {"title": ("Бюллетень НБКР " + tit) if tit else "Бюллетень НБКР", "file": fname, "new": new,
            "port": {"years": port["years"]} if port else {"years": {}}}


def nbkr_parse_file(path):
    with open(path, "rb") as fh:
        data = fh.read()
    return nbkr_extract(xlsx_sheets(data, ("Титул", NBKR_TABLE_NEW, NBKR_TABLE_PORT)), os.path.basename(path))


def _norm_rate_map(d, key_re):
    out = {}
    if not isinstance(d, dict):
        return out
    for p in sorted(d):
        if not isinstance(p, str) or not re.match(key_re, p) or not isinstance(d[p], dict):
            continue
        row = {}
        for k, _n in NBKR_SECTORS:
            e = d[p].get(k)
            if isinstance(e, list) and len(e) == 2 and all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in e):
                rt, vol = float(e[0]), float(e[1])
                if rt == rt and vol == vol and 0 < rt < 100 and vol > 0:
                    row[k] = [rt, vol]
        if row:
            out[p] = row
    return out


def norm_nbkr(raw, notes):
    """Проверяет загруженный бюллетень в настройках; неверные записи отбрасываются."""
    if raw is None:
        return None
    if not isinstance(raw, dict) or not isinstance(raw.get("new"), dict):
        notes.append("Данные бюллетеня НБКР в настройках повреждены — не используются.")
        return None
    new = {"years": _norm_rate_map(raw["new"].get("years"), r"^\d{4}$"),
           "months": _norm_rate_map(raw["new"].get("months"), r"^\d{4}-(0[1-9]|1[0-2])$")}
    if not new["years"] and not new["months"]:
        notes.append("В данных бюллетеня НБКР нет ни одной ставки — бюллетень не используется.")
        return None
    port = raw.get("port") if isinstance(raw.get("port"), dict) else {}
    return {"title": raw_str(raw.get("title")) or "Бюллетень НБКР", "file": raw_str(raw.get("file")),
            "new": new, "port": {"years": _norm_rate_map(port.get("years"), r"^\d{4}$")}}


def nbkr_rate(nb, sector, pi):
    """Ставка бюллетеня для отрасли за отчётный период компании: (ставка %, подпись периода) или (None, причина)."""
    ry = pi["report_year"]
    if pi["fy_type"] == "year":
        if ry is None:
            return None, "не указан последний полный финансовый год"
        e = nb["new"]["years"].get("%04d" % ry, {}).get(sector)
        if e is None:
            return None, "нет годовой ставки за %d год" % ry
        return e[0], "%d г." % ry
    bal = pi["bal"]
    if bal is None:
        return None, "не указана дата баланса"
    n = 12 if pi["fy_type"] == "ltm" else pi["interim_months"]
    y, m = int(bal[0:4]), int(bal[5:7])
    keys = []
    for i in range(n):
        t = y * 12 + (m - 1) - i
        keys.append("%04d-%02d" % (t // 12, t % 12 + 1))
    keys.reverse()
    # среднее арифметическое помесячных ставок — так НБКР считает годовую ставку в той же таблице
    # (годовая = среднее 12 месяцев; LTM на 31.12 совпадает с годовой ставкой)
    sr = 0.0
    for k in keys:
        e = nb["new"]["months"].get(k, {}).get(sector)
        if e is None:
            return None, "нет помесячных данных за %s.%s" % (k[5:7], k[0:4])
        sr += e[0]
    lab = "%s.%s–%s.%s" % (keys[0][5:7], keys[0][0:4], keys[-1][5:7], keys[-1][0:4])
    return sr / len(keys), lab


def nbkr_sector_of(st, code):
    ov = st["subsectors"].get(code, {})
    return ov.get("nbkr_sector") or NBKR_DEFAULT_MAP.get(code)

