    itm = compute(dict(pz2, report_year=2024, fy_type="interim", interim_months=6, interim_typical=True, bal_date="30.06.2025"), sb)
    chk("Промежуточная отчётность 6 мес.: среднее за 01.2025–06.2025", abs(itm["b4"]["int"]["market"] * 100 - q(sum(16.0 + m * 0.1 for m in range(1, 7)) / 6.0, 2)) < 1e-9
        and "01.2025–06.2025" in itm["b4"]["int"]["market_note"], itm["b4"]["int"].get("market_note"))
    kw = compute(dict(pz2, key_rate=20), sb)
