    chk("Рыночная ставка выше ключевой → без такого предупреждения", not any("ниже ключевой ставки НБКР" in w for w in rb_["warnings"]))
    bd = compute(DEMO_CASES["dairy"]["inputs"])
    ef = bd["b4"]["int"]["eff"]
    sl, _n3 = normalize_settings({"market_rate": q(ef * 50, 2)})
