    r24 = compute(dict(pz2, report_year=2024, bal_date="31.12.2024"), sb)
    chk("Нет ставки за отчётный год → общая ставка и предупреждение", r24["b4"]["int"]["market_src"] == "all" and any("нет годовой ставки за 2024 год" in w for w in r24["warnings"]))
    so2, _n2 = normalize_settings({"nbkr": nbs, "subsectors": {"PRM": {"market_rate": 19}}})
    chk("Своя ставка подсектора важнее бюллетеня", compute(pz2, so2)["b4"]["int"]["market_src"] == "sub")
    chk("Ставка аналитика с источником важнее бюллетеня", compute(dict(pz2, mkt_rate=14, s_mkt_rate="справка банка"), sb)["b4"]["int"]["market_src"] == "input")
    so3, _n3 = normalize_settings({"nbkr": nbs, "subsectors": {"PRM": {"nbkr_sector": "ind"}}})
