# ════════════════════════════════════════════════════════════════════════════
# 16. АРХИВ ОЦЕНОК И НАСТРОЙКИ
# ════════════════════════════════════════════════════════════════════════════

ARCHIVE_FORMAT = "kyrgyz-rating-archive/2"
ARCHIVE_STATUSES = ARCHIVE_STATUSES_CFG
ARCHIVE_STATUS_VALUES = [x["value"] for x in ARCHIVE_STATUSES]

def _here():
    return os.path.dirname(os.path.abspath(__file__))

def default_archive_path():
    return os.path.join(_here(), "kyrgyz_rating_archive.json")

def legacy_archive_path():
    return os.path.join(_here(), "kg_agro_rating_archive.json")

def default_settings_path():
    return os.path.join(_here(), "kyrgyz_rating_settings.json")

def _now_iso():
    import datetime
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")

def entry_summary(res, raw, settings):
    rated = res["status"] == "rated"
    sub = res.get("main")
    return {
        "model": MODEL_VERSION, "company": raw_str(raw.get("company")), "inn": raw_str(raw.get("inn")), "analyst": raw_str(raw.get("analyst")),
        "eval_date": raw_str(raw.get("eval_date")), "report_year": raw_str(raw.get("report_year")),
        "subsector": sub, "subsector_name": SUBSECTORS[sub]["name"] if sub in SUBSECTORS else "",
        "calc_status": res["status"], "message": res.get("message"),
        "agg": res.get("agg"), "base_national": res["rating_base"]["national"] if res.get("rating_base") else None,
        "notches": res["adj"]["notches"] if res.get("adj") else None,
        "final_index": res.get("index") if rated else None,
        "final_internal": res["rating"]["internal"] if rated else None,
        "final_national": res["rating"]["national"] if rated else None,
        "outlook_code": res["outlook"]["code"] if rated else None, "outlook_label": res["outlook"]["label"] if rated else None,
        "input_hash": res["input_hash"], "result_hash": res["result_hash"],
        "inputs": raw, "settings": settings,
    }

def make_entry(raw, settings=None, status="draft", note="", saved_at=None, eid=None):
    st, _n2 = normalize_settings(settings) if settings is not None else (default_settings(), [])
    res = compute(raw, st)
    e = entry_summary(res, raw, st)
    saved_at = saved_at or _now_iso()
    e["saved_at"] = saved_at
    e["updated_at"] = _now_iso()
    e["id"] = eid or ("k" + "".join(ch for ch in saved_at if ch.isdigit())[:14] + "-" + e["input_hash"][:8])
    e["status"] = status if status in ARCHIVE_STATUS_VALUES else "draft"
    e["note"] = "" if note is None else str(note)
    return e

def load_archive(path=None):
    path = path or default_archive_path()
    if not os.path.exists(path):
        return {"format": ARCHIVE_FORMAT, "entries": []}
    with open(path, "r", encoding="utf-8") as fh:
        data = json.load(fh)
    if isinstance(data, list):
        data = {"format": ARCHIVE_FORMAT, "entries": data}
    data.setdefault("entries", [])
    return data

def load_legacy_archive(path=None):
    """Оценки прежней программы: только для просмотра (пересчитать по новому скоркарду нельзя — другой набор данных)."""
    path = path or legacy_archive_path()
    if not os.path.exists(path):
        return []
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except Exception:
        return []
    entries = data.get("entries", []) if isinstance(data, dict) else (data if isinstance(data, list) else [])
    out = []
    for e in entries:
        if isinstance(e, dict):
            out.append({"id": e.get("id"), "company": e.get("company_name"), "saved_at": e.get("saved_at"), "subsector_name": e.get("subsector_name"),
                        "final_national": e.get("final_national"), "outlook_label": e.get("outlook_label"), "analyst": e.get("analyst"),
                        "period": e.get("period_label"), "status": e.get("status"), "note": e.get("note")})
    return out

def write_json_atomic(data, path):
    folder = os.path.dirname(os.path.abspath(path))
    if folder and not os.path.exists(folder):
        os.makedirs(folder)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(data, fh, ensure_ascii=False, indent=1)
    if os.path.exists(path):
        import shutil
        shutil.copyfile(path, path + ".bak")
    os.replace(tmp, path)

def _sort_entries(entries):
    return sorted(entries, key=lambda e: (e.get("saved_at") or "", e.get("id") or ""), reverse=True)

def archive_upsert(entries_in, path=None):
    """Сохраняет записи. Python пересчитывает каждую запись по её данным и настройкам и отмечает,
    совпал ли хэш результата с присланным интерфейсом (verified)."""
    data = load_archive(path)
    by_id = {}
    for e in data["entries"]:
        by_id[e["id"]] = e
    saved = []
    for ein in entries_in:
        if not isinstance(ein, dict) or not isinstance(ein.get("inputs"), dict):
            continue
        e = make_entry(ein["inputs"], ein.get("settings"), ein.get("status", "draft"), ein.get("note", ""), ein.get("saved_at"), ein.get("id"))
        client = ein.get("result_hash")
        e["verified"] = (client == e["result_hash"]) if client else None
        if isinstance(ein.get("process"), dict):
            e["process"] = ein["process"]
            ok, errs = process_verify(e)
            if ok is not None:
                e["process_ok"] = ok
                e["process_errors"] = errs
                if ok:
                    e["status"] = expected_status(e)
        by_id[e["id"]] = e
        saved.append(e["id"])
    data["entries"] = _sort_entries(list(by_id.values()))
    data["format"] = ARCHIVE_FORMAT
    write_json_atomic(data, path or default_archive_path())
    return data, saved

def archive_delete(eid, path=None):
    data = load_archive(path)
    data["entries"] = [e for e in data["entries"] if e.get("id") != eid]
    write_json_atomic(data, path or default_archive_path())
    return data

def archive_verify(path=None, deep_files=True):
    out = []
    folder = files_dir(path)
    for e in load_archive(path)["entries"]:
        r = compute(e["inputs"], e.get("settings"))
        docs = docs_of(e["inputs"])
        miss = [m.get("name") or m["id"][:12] for _k, m in docs if not file_ok(folder, m["id"], deep_files)]
        pok, perr = process_verify(e)
        out.append({"id": e["id"], "company": e.get("company"), "ok": r["result_hash"] == e.get("result_hash"),
                    "same_model": e.get("model") == MODEL_VERSION,
                    "final_now": r["rating"]["national"] if r["status"] == "rated" else r.get("message"), "final_saved": e.get("final_national") or e.get("message"),
                    "docs": len(docs), "docs_missing": miss, "process_ok": pok, "process_errors": perr})
    return out

def load_settings(path=None):
    path = path or default_settings_path()
    if not os.path.exists(path):
        return default_settings()
    with open(path, "r", encoding="utf-8") as fh:
        return normalize_settings(json.load(fh))[0]

def save_settings(raw, path=None):
    data = normalize_settings(raw)[0]
    write_json_atomic(data, path or default_settings_path())
    return data

def _csv_num(x, d=2):
    return "" if not is_num(x) else fmt_fixed(x, d).replace(".", ",")

def _csv_process(e):
    d = _d(_d(e.get("process")).get("decision"))
    ndocs = len(docs_of(e.get("inputs")))
    if not d.get("status"):
        return ["", "", "", "", "", "", ndocs or ""]
    return [d.get("decision_label"), d.get("protocol"), d.get("date"), d.get("final_national"), d.get("outlook_label"),
            deviation_text(d.get("deviation")), ndocs or ""]

def archive_csv(entries):
    status = {}
    for x in ARCHIVE_STATUSES:
        status[x["value"]] = x["label"]
    head = ["Дата сохранения", "Компания", "ИНН", "Подсектор", "Последний полный год", "Аналитик", "Дата оценки", "Балл скоркарда",
            "Оценка по баллу", "Корректировки, ступ.", "Итоговая оценка", "Итоговая (внутр.)", "Прогноз", "Результат расчёта",
            "Статус", "Комментарий", "Решение комитета", "Протокол", "Дата решения", "Оценка комитета", "Прогноз комитета",
            "Отклонение от программы", "Документов", "Код расчёта"]

    def cell(v):
        v = "" if v is None else str(v)
        if any(c in v for c in (";", '"', "\n", "\r")):
            v = '"' + v.replace('"', '""') + '"'
        return v
    rows = [";".join(head)]
    for e in entries:
        rows.append(";".join(cell(v) for v in [
            (e.get("saved_at") or "")[:19].replace("T", " "), e.get("company"), e.get("inn"), e.get("subsector_name"), e.get("report_year"),
            e.get("analyst"), e.get("eval_date"), _csv_num(e.get("agg"), 2), e.get("base_national"), e.get("notches"),
            e.get("final_national"), e.get("final_internal"), e.get("outlook_label"), e.get("message") or "Оценка рассчитана",
            status.get(e.get("status"), e.get("status")), e.get("note")] + _csv_process(e) + [e.get("result_hash")]))
    return "﻿" + "\r\n".join(rows) + "\r\n"

# ════════════════════════════════════════════════════════════════════════════
# 17. ЛОКАЛЬНЫЙ СЕРВЕР (стандартная библиотека)
# ════════════════════════════════════════════════════════════════════════════

def _slim(res):
    out = dict(res)
    return out

def serve(port=8765, html_path=None, archive_path=None):
    import threading
    from urllib.parse import urlparse, parse_qs
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    if not html_path:
        # рядом с движком: kg_agro_rating.html или index.html (так файл лежит в репозитории GitHub)
        html_path = os.path.join(_here(), "kg_agro_rating.html")
        if not os.path.exists(html_path) and os.path.exists(os.path.join(_here(), "index.html")):
            html_path = os.path.join(_here(), "index.html")
    archive_path = os.path.abspath(archive_path or default_archive_path())
    settings_path = os.path.join(os.path.dirname(archive_path), "kyrgyz_rating_settings.json")
    legacy_path = os.path.join(os.path.dirname(archive_path), "kg_agro_rating_archive.json")
    files_path = files_dir(archive_path)
    max_bytes = DOCS_CFG["max_mb"] * 1024 * 1024
    lock = threading.Lock()

    class H(BaseHTTPRequestHandler):
        def _send(self, code, body, ctype="application/json; charset=utf-8"):
            data = body if isinstance(body, bytes) else body.encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Access-Control-Allow-Headers", "Content-Type, X-File-Id")
            self.send_header("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS")
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(data)

        def _json(self, code, obj):
            self._send(code, json.dumps(obj, ensure_ascii=False))

        def do_OPTIONS(self):
            self._send(204, b"")

        def _file(self, u):
            fid = u.path[len("/api/files/"):]
            if not file_ok(files_path, fid):
                return self._json(404, {"error": "файл не найден"})
            q = parse_qs(u.query)
            name = (q.get("name") or ["document"])[0]
            ctype = (q.get("type") or [""])[0]
            inline = ctype in DOCS_CFG["inline_types"]
            if not inline:
                ctype = "application/octet-stream"
            from urllib.parse import quote
            with open(os.path.join(files_path, fid), "rb") as fh:
                data = fh.read()
            self.send_response(200)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Content-Disposition", "%s; filename*=UTF-8''%s" % ("inline" if inline else "attachment", quote(name, safe="")))
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Content-Security-Policy", "sandbox")
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(data)

        def do_GET(self):
            u = urlparse(self.path)
            if u.path.startswith("/api/files/"):
                return self._file(u)
            if u.path == "/api/files":
                ids = [x for x in (parse_qs(u.query).get("ids") or [""])[0].split(",") if x]
                return self._json(200, {"present": [i for i in ids if file_ok(files_path, i)]})
            if self.path in ("/", "/index.html"):
                if os.path.exists(html_path):
                    with open(html_path, "rb") as fh:
                        self._send(200, fh.read(), "text/html; charset=utf-8")
                else:
                    self._send(404, "HTML-файл интерфейса не найден: " + html_path, "text/plain; charset=utf-8")
            elif self.path == "/api/health":
                self._json(200, {"engine": "python", "version": MODEL_VERSION, "archive": True, "archive_path": archive_path,
                                 "settings": True, "settings_path": settings_path, "files": True, "files_path": files_path})
            elif self.path == "/api/settings":
                with lock:
                    data = load_settings(settings_path)
                self._json(200, {"path": settings_path, "settings": data})
            elif self.path == "/api/archive":
                with lock:
                    data = load_archive(archive_path)
                self._json(200, {"path": archive_path, "entries": data["entries"]})
            elif self.path == "/api/archive-legacy":
                self._json(200, {"path": legacy_path, "entries": load_legacy_archive(legacy_path)})
            elif self.path == "/api/config":
                cx = dict(CONFIG)
                cx["golden"] = GOLDEN
                self._json(200, cx)
            else:
                self._json(404, {"error": "not found"})

        def do_DELETE(self):
            u = urlparse(self.path)
            if u.path != "/api/archive":
                return self._json(404, {"error": "not found"})
            eid = (parse_qs(u.query).get("id") or [""])[0]
            try:
                with lock:
                    data = archive_delete(eid, archive_path)
                self._json(200, {"path": archive_path, "entries": data["entries"]})
            except Exception as ex:
                self._json(400, {"error": str(ex)})

        def do_POST(self):
            n = int(self.headers.get("Content-Length", "0"))
            if self.path.split("?")[0] == "/api/files":
                if n > max_bytes:
                    left = n
                    while left > 0:
                        left -= len(self.rfile.read(min(left, 1 << 20)) or b"x" * left)
                    return self._json(413, {"error": "файл больше %d МБ" % DOCS_CFG["max_mb"]})
                data = self.rfile.read(n)
                with lock:
                    fid = file_store(data, files_path)
                want = self.headers.get("X-File-Id")
                if want and want != fid:
                    return self._json(400, {"error": "контрольная сумма файла не совпала — повторите загрузку"})
                return self._json(200, {"id": fid, "size": len(data)})
            try:
                payload = json.loads(self.rfile.read(n).decode("utf-8") or "{}")
            except Exception as ex:
                return self._json(400, {"error": "неверный JSON: " + str(ex)})
            try:
                if self.path == "/api/settings":
                    with lock:
                        data = save_settings(payload.get("settings") or {}, settings_path)
                    return self._json(200, {"path": settings_path, "settings": data})
                if self.path == "/api/archive":
                    items = payload.get("entries") if isinstance(payload.get("entries"), list) else [payload.get("entry")]
                    with lock:
                        data, saved = archive_upsert(items, archive_path)
                    return self._json(200, {"path": archive_path, "entries": data["entries"], "saved": saved})
                if self.path == "/api/rate":
                    inputs = payload.get("inputs") if isinstance(payload.get("inputs"), dict) else payload
                    return self._json(200, compute(inputs, payload.get("settings")))
                if self.path == "/api/report":
                    inputs = payload.get("inputs") if isinstance(payload.get("inputs"), dict) else payload
                    return self._send(200, committee_report_md(compute(inputs, payload.get("settings")), inputs), "text/markdown; charset=utf-8")
                return self._json(404, {"error": "not found"})
            except Exception as ex:
                self._json(400, {"error": str(ex)})

        def log_message(self, fmt, *args):
            pass

    srv = ThreadingHTTPServer(("127.0.0.1", port), H)
    print("Kyrgyz Rating: http://127.0.0.1:%d  (Ctrl+C — остановить)" % port)
    print("Интерфейс: %s" % html_path)
    print("Архив оценок: %s" % archive_path)
    print("Настройки: %s" % settings_path)
    print("Документы: %s" % files_path)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass

# ════════════════════════════════════════════════════════════════════════════
# 18. КОМАНДНАЯ СТРОКА
# ════════════════════════════════════════════════════════════════════════════

def _arg(args, name, default=None):
    if name in args:
        i = args.index(name)
        if i + 1 < len(args):
            return args[i + 1]
    return default

def main(argv):
    if hasattr(sys.stdout, "reconfigure"):
        try:
            sys.stdout.reconfigure(encoding="utf-8")
        except Exception:
            pass
    if len(argv) < 2 or argv[1] in ("-h", "--help", "help"):
        print(__doc__)
        return 0
    cmd = argv[1]
    if cmd == "selftest":
        ok, _c = selftest(True)
        return 0 if ok else 1
    if cmd == "demo":
        key = argv[2] if len(argv) > 2 else "dairy"
        if key not in DEMO_CASES:
            print("Доступные примеры:", ", ".join(DEMO_ORDER))
            return 1
        print(committee_report_md(compute(DEMO_CASES[key]["inputs"]), DEMO_CASES[key]["inputs"]))
        return 0
    if cmd == "rate":
        if len(argv) < 3:
            print("Укажите JSON-файл с данными компании")
            return 1
        with open(argv[2], "r", encoding="utf-8") as fh:
            data = json.load(fh)
        settings = None
        if isinstance(data, dict) and isinstance(data.get("inputs"), dict):
            settings = data.get("settings")
            data = data["inputs"]
        sp = _arg(argv, "--settings")
        if sp:
            settings = load_settings(sp)
        res = compute(data, settings)
        md = committee_report_md(res, data)
        if _arg(argv, "--md"):
            with open(_arg(argv, "--md"), "w", encoding="utf-8") as fh:
                fh.write(md)
        if _arg(argv, "--json"):
            with open(_arg(argv, "--json"), "w", encoding="utf-8") as fh:
                json.dump(res, fh, ensure_ascii=False, indent=1)
        print(md)
        return 0
    if cmd == "export-config":
        cx = dict(CONFIG)
        cx["golden"] = GOLDEN
        txt = json.dumps(cx, ensure_ascii=False, indent=1)
        if len(argv) > 2:
            with open(argv[2], "w", encoding="utf-8") as fh:
                fh.write(txt)
        else:
            print(txt)
        return 0
    if cmd == "serve":
        serve(int(_arg(argv, "--port", "8765")), _arg(argv, "--html"), _arg(argv, "--archive"))
        return 0
    if cmd == "archive":
        path = _arg(argv, "--archive") or default_archive_path()
        entries = load_archive(path)["entries"]
        print("Архив: %s — записей: %d" % (path, len(entries)))
        st = {}
        for x in ARCHIVE_STATUSES:
            st[x["value"]] = x["label"]
        for e in entries:
            print("  %s  %-40s %-10s балл %-6s %-16s %s" % ((e.get("saved_at") or "")[:16].replace("T", " "), (e.get("company") or "—")[:40],
                  e.get("final_national") or "—", fmt_num(e.get("agg"), 2), e.get("outlook_label") or "—", st.get(e.get("status"), "")))
        return 0
    if cmd == "archive-csv":
        if len(argv) < 3 or argv[2].startswith("--"):
            print("Укажите файл: python kg_agro_rating.py archive-csv archive.csv [--archive путь]")
            return 1
        path = _arg(argv, "--archive") or default_archive_path()
        with open(argv[2], "w", encoding="utf-8", newline="") as fh:
            fh.write(archive_csv(load_archive(path)["entries"]))
        print("Сохранено:", argv[2])
        return 0
    if cmd == "archive-import":
        if len(argv) < 3:
            print("Укажите JSON-файл, выгруженный из интерфейса (Архив → Скачать JSON)")
            return 1
        path = _arg(argv, "--archive") or default_archive_path()
        with open(argv[2], "r", encoding="utf-8") as fh:
            src = json.load(fh)
        items = src.get("entries", []) if isinstance(src, dict) else src
        data, saved = archive_upsert(items, path)
        print("Импортировано записей: %d; всего в архиве: %d" % (len(saved), len(data["entries"])))
        return 0
    if cmd == "archive-verify":
        path = _arg(argv, "--archive") or default_archive_path()
        rows = archive_verify(path)
        bad = 0
        for r in rows:
            mark = "✓" if r["ok"] else ("~" if not r["same_model"] else "✗")
            if not r["ok"] and r["same_model"]:
                bad += 1
            extra = ""
            if r["docs"]:
                extra += "  документов %d%s" % (r["docs"], (", нет файлов: " + ", ".join(r["docs_missing"])) if r["docs_missing"] else "")
            if r["process_ok"] is not None:
                extra += "  протокол " + ("✓" if r["process_ok"] else "✗ " + "; ".join(r["process_errors"]))
            if r["docs_missing"] or r["process_ok"] is False:
                bad += 1
            print("  %s %-40s сохранено %-12s сейчас %-12s%s" % (mark, (r["company"] or "—")[:40], r["final_saved"], r["final_now"], extra))
        print("Записей: %d, с ошибками: %d" % (len(rows), bad))
        return 0 if bad == 0 else 1
    if cmd == "monitoring":
        import datetime
        path = _arg(argv, "--archive") or default_archive_path()
        t = _arg(argv, "--today")
        today = date_iso(t) if t else datetime.date.today().isoformat()
        if not today:
            print("Дата --today: формат ДД.ММ.ГГГГ")
            return 1
        mon = monitoring(load_archive(path)["entries"], today)
        c = mon["counts"]
        print("Мониторинг на %s: действующих оценок %d, пересмотр просрочен %d, скоро %d, отозвано %d" % (
            iso_ru(today), c["active"], c["overdue"], c["soon"], c["withdrawn"]))
        for a in mon["active"]:
            print("  %-12s %-40s %-8s %-14s решение %s, протокол %s; пересмотр до %s (%s)%s" % (
                a["review_label"][:12], (a["company"] or "—")[:40], a["national"], a["outlook_label"], a["date"], a["protocol"],
                a["next_review"], a["review_basis"], "; в работе: %d" % a["in_work"] if a["in_work"] else ""))
        print("Рейтинговые действия:")
        for a in reversed(mon["actions"]):
            print("  %s  %-40s %-22s %s%s" % (a["date"], (a["company"] or "—")[:40], a["action_label"],
                  ((a["prev_national"] or "") + " → " if a["prev_national"] and a["national"] and a["prev_national"] != a["national"] else ""),
                  a["national"] or (a["reason"] or "")))
        return 0
    if cmd == "nbkr":
        if len(argv) < 3 or argv[2].startswith("--"):
            print("Укажите файл бюллетеня НБКР (.xlsx / .xls)")
            return 1
        try:
            nb = nbkr_parse_file(argv[2])
        except (ValueError, KeyError, OSError) as e:
            print("Не удалось прочитать бюллетень: %s" % e)
            return 1
        st_raw = {}
        sp = _arg(argv, "--settings")
        if sp:
            with open(sp, "r", encoding="utf-8") as fh:
                st_raw = json.load(fh)
        st_raw["nbkr"] = nb
        st, notes = normalize_settings(st_raw)
        ys = sorted(nb["new"]["years"])
        ms = sorted(nb["new"]["months"])
        print("%s (%s): годовые ставки %s–%s, помесячные %s – %s" % (nb["title"], nb["file"], ys[0] if ys else "—", ys[-1] if ys else "—",
              ms[0] if ms else "—", ms[-1] if ms else "—"))
        print("Новые кредиты в сомах, средневзвешенная ставка, %:")
        print("  %-26s" % "Отрасль" + "".join("%9s" % y for y in ys[-3:]))
        for k, nm in NBKR_SECTORS:
            print("  %-26s" % NBKR_SECTOR_NAMES[k] + "".join("%9s" % (("%.2f" % nb["new"]["years"][y][k][0]).replace(".", ",") if k in nb["new"]["years"][y] else "—") for y in ys[-3:]))
        print("Подсекторы → отрасль бюллетеня:")
        for c in SUBSECTOR_ORDER:
            sec = nbkr_sector_of(st, c)
            print("  %-42s %s" % (SUBSECTORS[c]["name"], NBKR_SECTOR_NAMES[sec] if sec else "по долям сегментов"))
        for n_ in notes:
            print("! " + n_)
        out = _arg(argv, "--out")
        if out:
            with open(out, "w", encoding="utf-8") as fh:
                json.dump(st, fh, ensure_ascii=False, indent=1)
            print("Настройки с бюллетенем записаны: %s (загрузите их в программе: «Настройки» → «Загрузить настройки»)" % out)
        return 0
    if cmd == "next-year":
        import datetime
        if len(argv) < 3 or argv[2].startswith("--"):
            print("Укажите JSON-файл с данными оценки")
            return 1
        with open(argv[2], "r", encoding="utf-8") as fh:
            data = json.load(fh)
        settings = None
        if isinstance(data, dict) and isinstance(data.get("inputs"), dict):
            settings = data.get("settings")
            data = data["inputs"]
        t = _arg(argv, "--today")
        today = date_iso(t) if t else datetime.date.today().isoformat()
        if not today:
            print("Дата --today: формат ДД.ММ.ГГГГ")
            return 1
        ny, err = next_year_inputs(data, today)
        if err:
            print(err)
            return 1
        out = argv[3] if len(argv) > 3 and not argv[3].startswith("--") else None
        doc = {"model": MODEL_VERSION, "saved_at": datetime.datetime.now(datetime.timezone.utc).isoformat(), "inputs": ny, "settings": settings}
        if out:
            with open(out, "w", encoding="utf-8") as fh:
                json.dump(doc, fh, ensure_ascii=False, indent=1)
        pi = period_info(ny)
        print("Новая оценка: %s, последний полный финансовый год %s, дата баланса %s, дата оценки %s" % (
            raw_str(ny.get("company")) or "—", ny["report_year"], ny.get("bal_date") or "—", ny["eval_date"]))
        print("Таблица «по годам»: %s — столбец %d пуст, прошлые годы перенесены" % (", ".join(str(y) for y in pi["years"]), pi["years"][0]))
        if out:
            print("Записано:", out)
        return 0
    print("Неизвестная команда:", cmd)
    print(__doc__)
    return 1

if __name__ == "__main__":
    sys.exit(main(sys.argv))
